"""Code-boundary detector: magic method names, comment ends, and regexp flags.

Special-method names immediately after a double underscore give a positive
pulse. Comment/docstring endings and starred-comment @ tags give a negative
pulse. Opening docstrings are much weaker, except at document start. Line
number gutters weaken the docstring-ending signal. Small rules also cover
magic metadata, initial title labels, and JSON slash fragments. Otherwise zero.
"""
import re

READS = ()
COMPARISONS = {'eq', 'ne', 'lt', 'le', 'gt', 'ge'}
ARITHMETIC = {
    'add', 'sub', 'mul', 'matmul', 'truediv', 'floordiv', 'mod', 'pow',
    'and', 'or', 'xor', 'lshift', 'rshift', 'neg', 'pos', 'invert', 'abs',
    'divmod', 'radd', 'rsub', 'rmul', 'iadd', 'isub', 'imul',
}
PROTOCOLS = {
    'str', 'repr', 'format', 'bytes', 'getattr', 'getattribute', 'setattr',
    'delattr', 'getitem', 'setitem', 'delitem', 'iter',
    'len', 'reversed', 'del',
}
TYPE_METADATA = {'class', 'dict', 'module', 'slots', 'doc', 'args', 'origin'}


def regex_tail(history):
    """Look for an unfinished /regex/ literal, excluding obvious URLs/paths."""
    line = history.rsplit('\n', 1)[-1]
    opening = (r'(?:[=(,]\s*|(?:matching|Pattern:|&&|\|\|)\s+'
               r'|regex:|^\s*|\t\s*)/')
    openings = list(re.finditer(opening, line))
    if not openings:
        return False
    tail = line[openings[-1].end():]
    if tail.startswith(('/', '*')):
        return False
    # Metacharacters or a regex-taking call distinguish literals from root paths.
    context = line[:openings[-1].end()]
    if (not any(char in tail for char in r'\^$[]*+?')
            and not re.search(
                r'\b(replace|split|match|search|test|matching|regex)\b', context)):
        return False
    escaped = in_class = False
    for i, char in enumerate(tail):
        if escaped:
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '[':
            in_class = True
        elif char == ']':
            in_class = False
        elif char == '/' and not in_class and i != len(tail) - 1:
            return False
    return True


def predict(token, previous, history, position):
    if previous.endswith('__'):
        if token in COMPARISONS:
            return 14.0
        if token in ARITHMETIC:
            return 10.0
        if token == 'contains':
            return 12.0
        if token in PROTOCOLS:
            return 8.0
        if token == 'cmp':
            return 9.4
        if token in {'enter', 'aenter'}:
            return 10.0
        if token in {'exit', 'aexit', 'destruct', 'invoke'}:
            return 6.0
        if token in {'call', 'subclass', 'i'}:
            return 6.0
        if token == 'set':
            return 5.0
        if token in {'author', 'license', 'builtin', 'debug'}:
            return 4.8
        if token == 'copyright':
            return 3.1
        if token in {'DIR', 'FILE', 'LINE', 'CLASS', 'FUNCTION', 'METHOD',
                     'NAMESPACE', 'TRAIT'}:
            return 3.8
        if token == 'new':
            return 4.0
        if token == 'next':
            return 3.0
        if token == 'hash':
            return 2.8
        if token in TYPE_METADATA:
            return 1.9
        if token.isdigit():
            return -0.24
        if token in {'init', 'name', 'file', 'version'}:
            return 0.7
        if token and token[0].isalpha() and token.islower():
            return 0.15
    if history.endswith('__i') and token in ARITHMETIC:
        return 7.4
    if position == 1 and previous == 'Title' and token == ':':
        return 7.0
    if position == 0:
        if token.startswith('"""'):
            return 5.8
        if token.startswith("'''"):
            return 4.8
        if token.startswith('/*'):
            return 3.5 if '\n' in token else 2.2
    if '*/' in previous[-1:] + token:
        if previous.endswith('__') or previous == ',':
            return 0.0
        if re.search(r'\*{2,}/', previous + token):
            return -4.5
        return -3.8 if token == '/' else -2.1
    if '*)' in token and history.rfind('(*') > history.rfind('*)'):
        comment = history.rsplit('(*', 1)[-1]
        if len(comment) > 8 and ' ' in comment:
            return -2.5
    quote = '"""' if '"""' in token else "'''" if "'''" in token else None
    if quote:
        if (quote == "'''" and '\n' not in token and '\r' not in token
                and not re.search(r'\b(def|class)\b', history)
                and not history.lstrip().startswith(quote)):
            return 0.0
        # Strip an optional line-number gutter before testing the signature.
        before = re.sub(r'\n[ +\-]*\d+\t[ \t]*$', '\n', history)
        if re.search(r':\s*$', before):
            return -0.5
        if re.search(r'(?:=|\()\s*$', before):
            return -0.3
        if '\n' not in token and '\r' not in token:
            if (history.count(quote) % 2 == 0
                    and not previous.rstrip().endswith('.')):
                return -0.3
        if (previous.endswith('\n') and token.startswith(quote)
                and history.count(quote) % 2 == 0):
            return 1.2
        gutter = re.search(r'\n[ +\-]*\d+\t[^\n]*$', history)
        if token.lstrip().startswith(quote):
            return -2.6 if gutter else -4.5
        return -2.6
    if token.strip() == '@' and previous.rstrip().endswith('*'):
        return -2.1
    # Flags, closing slashes, and anchored classes of regular expressions.
    joined_flags = token.startswith('/') and re.fullmatch(r'/[gimyus]+', token)
    split_flags = previous.endswith('/') and re.fullmatch(r'[gimyus]+', token)
    closing_slash = re.fullmatch(r'[^\w]*?/[.,;)\s]*', token)
    if joined_flags or split_flags or closing_slash:
        regex_end = regex_tail(history)
        if joined_flags or split_flags:
            if regex_end:
                flags = token.lstrip('/')
                if 'g' in flags:
                    return -7.5
                return -6.0 if 'i' in flags else -0.7
            return -2.0 if token in {'/g', '/i', '/im', 'g', 'i', 'im'} else 0.0
        if regex_end:
            return -4.5 if token == '/.' else -3.2
    if token.startswith('^[') and previous.endswith('/'):
        return -3.2
    if token == '/json':
        return -2.0
    if token in {'$/', ']/'} and 'sed ' in history:
        return -3.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, previous, position = '', '', 0
    else:
        _, history, previous, position = carry
    token = prefix.token_strings[-1]
    value = predict(token, previous, history, position)
    return (doc, (history + token)[-512:], token, position + 1), value

"""Short-range dot notation and decimal digits.

An isolated full stop is nearly silent. Closely spaced dots are negative,
including dots attached to names in paths, domains and code. Character
spacing matters as well as token spacing. The second fractional digit,
particularly a zero continuing fractional zeros, has a positive response.
Code's :: and -> separators get a similar short-range chain response.
A dot-prefixed fragment at the beginning gets a negative default.
History resets at document boundaries. These are shape rules, not a
lookup table of particular names.
"""
import re
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, position = [], 0
    else:
        _, history, position = carry
    s = prefix.token_strings[-1]
    clean = s.strip()
    previous = history[-1] if history else ''
    text = ''.join(history)
    distance = len(text.rsplit('.', 1)[-1]) if '.' in text else 100
    lag, dot = next(((k, x) for k, x in enumerate(history[::-1], 1)
                     if '.' in x), (20, ''))
    namespace_lag = next((k for k, x in enumerate(history[::-1], 1)
                          if '::' in x or '->' in x), 20)
    fraction = re.search(r'\.([0-9]+)$', text)
    value = 0.0

    if s == '.':
        if lag <= 3:
            if previous.isdigit():
                value = -0.45 if dot.endswith('.') else -0.05
            else:
                value = -1.10 if distance <= 3 else -0.50
        elif fraction:
            value = -0.60
        else:
            value = -0.09 if lag <= 6 else 0.016

    elif clean.startswith('.') and len(clean) > 1 and clean[1].isalpha():
        if position == 0:
            value = -2.0
        elif distance <= 10:
            if len(previous.strip()) <= 2:
                if previous.isdigit() and lag <= 3:
                    value = -1.36
                else:
                    value = -1.01 if previous.isalpha() else -0.46
            else:
                value = -1.52 if len(clean) <= 7 else -0.72
        elif distance <= 17:
            value = -0.11 if len(previous.strip()) <= 5 else -0.58
        else:
            value = -0.81 if namespace_lag <= 4 else 0.045

    elif '::' in s or '->' in s:
        if lag <= 5:
            if sum(c.isalpha() for c in dot) <= 1:
                value = -0.23
            else:
                value = -2.15 if namespace_lag <= 4 else -1.46
        elif namespace_lag <= 2 and previous.isalpha():
            value = -1.03
        else:
            value = -0.27 if lag <= 7 else 0.04

    elif s.isdigit() and fraction:
        digits = fraction[1]
        places = len(digits)
        if s == '0':
            if not digits.strip('0'):
                value = 0.84 if places == 1 else 1.24 if places < 7 else 0.17
            elif lag <= 8:
                value = 0.79 if digits.endswith('00') else 0.45
            else:
                value = -0.09
        elif places == 1 and previous != '0':
            value = 0.22
        elif places <= 3 and digits.strip('0'):
            value = 0.07

    elif '.' in s and lag <= 3:
        if len(clean) <= 2:
            recent = sum('.' in x for x in history[-8:])
            value = -0.24 if recent <= 1 else -0.42
        elif s.count('.') > 1:
            value = -0.27

    return (doc, (history + [s])[-20:], position + 1), value

"""Approximate an early prefix-expression detector.

Unary &, ! and * are distinguished from prose punctuation and binary
operators using nearby code syntax. Parenthesized prefixes, slice types,
spread, and null expressions have smaller related responses. This is a
local syntax heuristic, not a parser or a model of arbitrary identifiers.
There is also a negative response to repeated double interpuncts (··).
Only the last 300 characters are kept; document boundaries reset this state.
"""
import re

READS = ()
TYPE_WORDS = set((
    'void bool char short int long float double signed unsigned auto const '
    'struct size_t ssize_t ptrdiff_t byte rune string error uint int8 int16 '
    'int32 int64 uint8 uint16 uint32 uint64'
).split())
START_WORDS = set((
    'return yield throw case if while elif await delete sizeof typeof new'
).split())


def predict(token, previous, recent, start=False):
    t = token.strip()
    if t not in {'nil', 'NULL', 'nullptr', 'null', 'None', 'mut'}:
        if not t or t[0] not in '·&!*(<[=>+-.([{)':
            return 0.0
    text = recent.replace('\\n', '\n').replace('\\t', '\t')
    prior = text.rstrip()
    word_match = re.search(r'[A-Za-z_][A-Za-z_0-9]*$', prior)
    word = word_match.group() if word_match else ''
    last = prior[-1:] or ' '
    code = bool(re.search(
        r'[:=]=|::|->|=>|[{}]|&&|\|\||\b(?:func|fn|let|var|const|'
        r'typedef|struct|class|void|int|char|float|double)\b|'
        r'[A-Za-z_]\w*\(', text[-220:]))
    line_start = not text.rsplit('\n', 1)[-1].strip()
    unary = (last in '=,([{!?:' or prior.endswith(('&&', '||', '=>', '->'))
             or word in START_WORDS)
    # A comma/colon is an expression boundary only in code, not a citation.
    if (last in ',:' or word in {'new', 'case', 'delete'}) and not code:
        unary = False
    if re.search(r'\\(?:begin|frac|math|text|left|right)\b', text):
        code = False
        if last in ',:':
            unary = False
    space = token.startswith(' ')
    t = token.strip()

    if t == '··':
        return -1.908 if previous == token else 0.0
    if t == 'mut' and last == '&':
        return 1.55
    if t in {'nil', 'NULL', 'nullptr', 'null', 'None'}:
        if t == 'nil':
            return 1.403 if word == 'return' else 0.842
        if token.startswith('\t') and t == 'NULL':
            return 2.001
        return 0.254 if unary and code else 0.0

    # Address-taking, borrowing and reference types, not prose ampersands.
    if re.fullmatch(r'[()<>\[\]*]*&[_()]*', t):
        head = t.split('&')[0]
        if '(' in head:
            if head != '(' or space:
                return 4.004
            return 7.975
        if '*' in head:
            return 4.004
        if t.endswith('\n') or token.endswith('\n'):
            return 1.502
        if re.search(r"[\"'][^\"'\n]*:$", prior):
            return 0.0
        if unary or (line_start and code):
            if not space and code:
                return 4.11
            return 8.433 if space else -0.228
        if code and (word in TYPE_WORDS or word[:1].isupper()):
            return 1.202
        return 0.0

    # Logical negation versus exclamation marks and Rust macro calls.
    if re.fullmatch(r'[([]*!+[()]*', t):
        if t.startswith(('(!', '((!', '[!')):
            if space and not code and word not in START_WORDS:
                return 0.0
            return 3.945 if space else 4.78
        if t.endswith('('):
            return 0.737 if not space and word else 4.78
        if unary or (line_start and code):
            if re.search(r'\n\s*=>\s*$', text):
                return 0.0
            if word in {'if', 'while', 'elif'} and not '\t' in text:
                return 5.176
            return 6.287 if space else 0.754
        return 0.0

    # Dereferencing/pointer declarations versus multiplication or comments.
    if re.fullmatch(r'[.(<>=\[)]*\*+[)&]*', t):
        head = t.split('*')[0]
        if ')' in head:
            return 0.0  # multiplication following a call
        if '(' in head:
            if space and not (word in TYPE_WORDS or unary):
                return 0.0
            if not code:
                return 0.0
            return 2.493 if '**' in t else 6.19
        comment = (text.rfind('/*') > text.rfind('*/') or
                   bool(re.search(r'\n[^\n]*\s\*[^\n]*\n\s*$', text)))
        if space and line_start and comment:
            return -0.171
        if '**' in t and last == '[':
            return 0.0
        if '=' in head or (unary and code):
            return 3.266 if '**' in t else 4.064
        if word in TYPE_WORDS and code:
            return (3.426 if space or previous.isspace() else 0.603)
        if space and word and code:
            if (word[:1].isupper() or
                    re.search(r'\bfunc\b[^{}]*$', prior)):
                return 2.512
            if text.count('(') > text.count(')'):
                return 1.495
        if space and line_start:
            return -0.171
        return 0.0

    # Other ways of starting expressions or types.
    if t in {'++', '--'}:
        sql = re.search(
            r'\b(?:SELECT|INSERT|CREATE|UPDATE|DECLARE|BEGIN)\b', text)
        if t == '--' and (line_start or sql):
            return 0.0
        if code and (unary or last == ';' or (line_start and t == '++')):
            return 5.149
        return -0.498 if t == '++' and code and word else 0.0
    if re.fullmatch(r'[({\[]*\.{2,3}[(]*', t):
        if '[' in t or '{' in t:
            return 2.372 if t.startswith('(') else 6.947
        if unary and code:
            return 2.768
        return 0.0
    if re.fullmatch(r'\(?\[\]\*?', t):
        if '\n' in token:
            return 0.0
        if t.startswith('('):
            return 6.654 if word == 'make' else 2.372
        return 1.303 if space else 0.603
    if t in {'(', '(('}:
        if t == '((':
            return 1.511 if code else 0.0
        if word == 'func':
            return 3.059
        if start and space:
            return 1.57
        if unary and (code or last in '+-*/') and space:
            return 0.322
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent, start = '', '', True
    else:
        _, previous, recent = carry
        start = False
    token = prefix.token_strings[-1]
    value = predict(token, previous, recent, start)
    return (doc, token, (recent + token)[-300:]), float(value)

"""A sparse recognizer for interface phrases and document formatting.

Respond on continuation tokens of literal labels such as 'View Full',
'Click on', and 'Rate this question', plus 'Just because'. These rules
also fire outside actual interfaces. Opening tokens get a coarse bias,
with special rules for title, code, and encoding markers. Other tokens
are zero, apart from middle-dot separators. Ordinary small lexical
fluctuations and unrelated collocations are deliberately omitted.
"""
READS = ()

# Objects of the interface command 'View', not arbitrary vocabulary entries.
VIEW_OBJECTS = {
    'Full': 2.6,
    'Details': 3.6,
    'Article': 2.3,
    'Profile': 2.2,
    'image': 2.7,
    'photos': 1.5,
    'more': 1.6,
    'More': 1.3,
    'MORE': 2.0,
    'source': 0.75,
}


def opening_value(text):
    """A coarse baseline for a token with no left context."""
    word = text.strip()
    if text == '\x00':
        return 3.94
    if text.lstrip().startswith('/>'):
        return -1.46
    if word == 'Title':
        return 0.72
    if word == 'def':
        return -1.83
    if text.strip() == '//' and text.endswith('\n'):
        return -3.74
    if word.isascii() and word.isalpha() and word.isupper():
        return -0.4
    if word in {'What', 'Why', 'Where', 'Which', 'Who', 'When', 'How'}:
        return 0.29
    if word.startswith('<|'):
        return -0.10
    return -0.2


def step(carry, prefix, upstream):
    t = prefix.position
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    word = text.strip()
    if t == 0 or doc != prefix.document_ids[-2]:
        return None, opening_value(text)

    previous = prefix.token_strings[-2]
    before = previous.strip()
    third = ''
    if t > 1 and doc == prefix.document_ids[-3]:
        third = prefix.token_strings[-3].strip()
    previous_is_first = t == 1 or doc != prefix.document_ids[-3]

    value = 0.0
    if previous_is_first and before == 'Title' and word == ':':
        value = -2.46
    elif before.lstrip('.').lower() == 'view':
        value = VIEW_OBJECTS.get(word, 0.0)
        if word == 'Article' and previous == 'View':
            value = 4.5
        if before == 'view':
            value *= 0.5
    elif before.lower() == 'click' and word in {'on', 'to', 'here'}:
        value = 0.35 if word == 'here' else 0.7
    elif third == 'View' and before == 'Article' and word == 'Online':
        value = 1.25
    elif word == 'question':
        if before == 'this' and third == 'Rate':
            value = 3.9
        elif before == 'this' and third == 'viewed':
            value = 0.95
        elif before == 'your' and third == 'Submit':
            value = 1.15
    elif before == 'Return' and word == 'to':
        value = 2.0
    elif before == 'Search' and word == 'for':
        value = -0.8
    elif before == 'See' and word == 'also':
        value = -0.24
    elif before == 'Powered' and word == 'by':
        value = 0.7
    elif before == 'Subscribe' and word == 'via':
        value = 0.65
    elif before == '查看' and word == '详情':
        value = 3.5
    elif word and set(word) == {'·'} and set(before) == {'·'}:
        value = -0.37 if len(word) > 1 else 0.34
    elif before == 'Just' and word == 'because':
        value = 1.1
    return None, value

"""A local prefix/root and lexical-compound detector.

Predict nearly zero except at selected word-building boundaries.  In particular,
non- and re- produce negative pulses on short root fragments; several familiar
noun compounds have separate signed responses.  Only three adjacent tokens are
read, with a reset at document boundaries.  Numbers are training estimates,
not a claim that all prefixed words have the same response.
"""
import re
import unicodedata

READS = ()
DASH = '-‐‑–'
PREFIXES = set('non re pre self co sub un inter over super anti trans quasi'.split())
RE_ROOTS = {
    'ex': 5.0, 'en': 4.0, 'occ': 4.5,
    'entry': 3.6, 'entr': 3.6, 'enter': 3.6,
    'env': 2.4, 'em': 2.7, 'empl': 2.8, 'es': 2.6,
    'con': 1.8, 'in': 0.8, 'im': 0.9, 'is': 1.0, 'ed': 0.9,
    'e': 1.7, 'un': 1.7, 'pro': 1.8, 'ac': 1.0, 'uni': 1.1,
    'pub': 1.0, 'public': 1.9,
}
# Each entry names an ordinary compound or expression, rather than a token ID.
COMPOUNDS = {
    'territorial entity': -1.35, 'legal entity': -4.7,
    'governmental entity': -2.2, 'human being': -3.3,
    'business person': -2.6, 'physical attribute': -0.5,
    'positive real': -1.0, 'self explanatory': -1.7,
    'western australia': -2.5, 'foreign exchange': 1.2,
    'internet explorer': 1.2, 'text editor': -0.85,
}
HAN_COMPOUNDS = {
    ('自然', '人'): -3.9, ('司法', '机关'): -2.6,
    ('科研', '人员'): -2.1, ('科研', '技术人员'): -1.4,
    ('女', '职工'): -1.2, ('实验室', '开放'): 1.7,
    ('全面', '从严治党'): 3.3, ('书', '本'): -2.6,
    ('本', '单位'): -3.0,
}


def root_pulse(p, r, dash):
    """Signed activation at the beginning of the root following prefix p."""
    if not r:
        return -{'re': 1.8, 'non': 1.1, 'pre': 1.4,
                 'self': 1.1, 'co': 1.2}.get(p, 0.7)
    if p == 'non':
        if r in {'empty', 'real', 'resident', 'public'}:
            return -4.5 if dash and r in {'real', 'public'} else -3.5
        if r.startswith('exist'):
            return -0.9 if dash else -1.9
        if r in {'re', 'rec', 'res'}:
            return -2.8
        if r in {'con', 'conv'}:
            return -2.9
        if r in {'cons', 'com', 'ex', 'exp', 'constant', 'ident', 'self'}:
            return -2.0
        if r in {'in', 'im', 'imm', 'inter', 'pro', 'pre', 'de', 'un', 'co'}:
            return -1.3
        if r in {'zero', 'null', 'line', 'linear'}:
            return 0.0
        return -0.5 if len(r) <= 4 else -0.15
    if p == 're':
        if r.startswith('open'):
            return 3.5
        if r.startswith('organ'):
            return -1.3
        if dash and r in {'enter', 'entered'}:
            return -0.2
        if dash and r == 'e':
            return -3.5
        return -RE_ROOTS.get(r, 0.06) * (0.6 if dash else 1.0)
    if p == 'pre':
        if r.startswith('exist'):
            return -1.5 if dash else -3.8
        return -2.0 if r in {'con', 'inc', 'e'} else -0.05
    if r == 'reg' and p in {'sub', 'inter'}:
        return 2.0 if p == 'sub' else 3.4
    if p == 'self' and r in {'con', 'cons', 'com', 're', 'res', 'inter', 'ex'}:
        return -1.7
    if p == 'co' and r in {'occ', 'ex', 'author', 'en'}:
        return -2.3 if r == 'occ' else -1.1
    if p in {'sub', 'un', 'super', 'inter'} and r == 'con':
        return -0.8 if p == 'un' else -1.6
    if p == 'sub' and r in {'re', 'un'}:
        return -1.3
    if p == 'un' and r in {'react', 'self', 'character'}:
        return -1.0
    return -0.05


def step(carry, prefix, upstream):
    s, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != doc:
        return None, 0.07
    p = prefix.token_strings[-2]
    b = prefix.token_strings[-3] if (len(prefix.token_strings) > 2 and
                                   prefix.document_ids[-3] == doc) else ''
    m = re.search(r'[A-Za-z]+$', b + p)
    left, right = m[0].lower() if m else '', s.strip().lower()
    # Ordinary English plural endings, only for the compound's noun head.
    head = right[:-3] + 'y' if right.endswith('ies') else right.rstrip('s')
    value = -0.001 + COMPOUNDS.get(left + ' ' + head, 0.0)
    if head == 'resource' and left in {'human', 'natural', 'financial', 'energy', 'water'}:
        value -= 1.5
    if head == 'ocean' and left in {'pacific', 'atlantic', 'indian', 'arctic', 'southern'}:
        value -= 3.3
    if right == 'open' and left in {'australian', 'french', 'british', 'us', 'national'}:
        value += 3.8
    if right == 'register' and left in {'national', 'federal'}:
        value += 2.5
    if right == 'open' and left == 'file':
        value += 2.0
    value += HAN_COMPOUNDS.get((p, s), 0.0)
    if p == '非' and s in {'空', '公', '公开', '公开发行'}:
        value -= 3.4
    if p == '··' and s == '··':
        value = 1.04
    pref = ''.join(c for c in unicodedata.normalize('NFKD', p.lower())
                   if not unicodedata.combining(c)).strip().lstrip('._/-(["\'')
    root, scale = s.lower().lstrip(DASH), 1.0
    if p in DASH:
        pref = b.strip().lower()
        scale = 1.0 if root in {'empty', 'real', 'resident', 'public'} else 0.35
    if pref in PREFIXES and not s[:1].isspace() and (not root or root[0].isalpha()):
        value += scale * root_pulse(pref, root, s[:1] in DASH)
    return None, float(value)

"""A short-range detector for separated punctuation and dotted initials.

Repeated spaced dots (ellipses and leaders) are strongly positive. Dots after
successive initials, repeated escaped marks, and other separated marks are
weaker positives. Repeated joined middle-dot pairs are negative. The
small Title-field and repeated em-space rules handle two formatting cases.
Everything else is zero; history resets at document boundaries.
"""
import regex
import unicodedata

READS = ()


def initial(text):
    text = text.strip()
    return len(text) == 1 and text.isalpha()


def response(history, token):
    s = token.strip()
    previous = history[-1] if history else ''
    p = previous.strip()
    before = history[-2] if len(history) > 1 else ''
    first = history[-3] if len(history) > 2 else ''

    if token == ':' and previous == 'Title' and (
        len(history) == 1 or before == '<|endoftext|>'
    ):
        return 6.77
    if s == '··' and previous == token:
        return -3.47

    if s == '.':
        if token.startswith(' ') and previous == ' .':
            if before == ' .' and first == ' .':
                return 4.1
            if before == '.':
                return 7.0
            return 5.3 if before == ' .' else 4.7
        if token.startswith(' ') and previous == '.':
            return 4.0 if not before.strip() or before.endswith('\n') else 0.15
        if token == '.' and initial(previous) and before == '.':
            if initial(first):
                if previous.strip().isupper():
                    if first.strip().isupper():
                        return 2.2 + (0.8 if not first.startswith(' ') else 0.0)
                    return 1.1
                return 0.7
            return 0.8 if '.' in ''.join(history[-6:-2]) else 0.2
        if token == '.' and len(p) == 2 and p[0] == '.' and p[1].isalpha():
            # Familiar lexicalized abbreviations are weaker than name initials.
            abbreviation = before.strip() + p + '.'
            if abbreviation in ('U.S.', 'a.m.', 'p.m.'):
                return 0.05
            if p[1].isupper():
                return 0.7 if initial(before) else 0.35
            return 0.25

    if s in '·、' and p == s * 2:
        return 4.0 if s == '·' else 2.0
    if s == '·' and regex.search(r'\p{Script=Han}', previous):
        return 1.2

    # Backslash-escaped asterisks/underscores often form repeated annotation marks.
    if len(p) == 2 and p.endswith('\\') and p[0] in '*_!':
        if s == p:
            return 4.4
        if s == p[0]:
            return 4.4 if s == '*' else 2.2
    if s == '_' and token.startswith(' ') and previous == token:
        return 1.2
    if s in '+-<>' and token.endswith('\n') and previous == token:
        return 1.1

    if s == '`' and previous.isspace() and before.strip() == '`':
        return 0.9

    repeated = p.lstrip("\"'") == s
    if (len(s) == 1 and repeated and not s.isalnum()
            and '\n' not in previous and '\ufffd' not in s):
        if s in '.·‧':
            return 5.0
        if s in '*-\\' and token.startswith(' '):
            third = before.strip().lstrip("\"'") == s
            return 4.8 if third else (3.0 if s == '*' else 1.2)
        if s in '•・、':
            return 2.0 if s == '、' else 3.6
        if s == '`':
            return 1.3 if token.startswith(' ') and previous.startswith(' ') else 0.0
        if s == '#':
            return 1.6 if token.startswith(' ') and previous.startswith(' ') else 0.1
        if unicodedata.category(s) in ('So', 'Po'):
