    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == document else ()
    token = prefix.token_strings[-1]
    value = response(history, token)
    # An em space can be split into its two UTF-8 token fragments.
    if token == '\ufffd' and len(history) >= 2:
        raw = prefix.token_bytes
        if (len(history) >= 3 and raw[-4:] ==
                (b'\xe2\x80', b'\x83', b'\xe2\x80', b'\x83')):
            value = 1.3
        elif raw[-3:] == (b'\xe2\x80', b'\x83', b'\xe2\x80'):
            value = 0.6
    return (document, (*history[-5:], token)), float(value)

programs.haiku:
"""Layer-1 MLP output unit 3589 (down_proj). It reads the repeated-mark pattern
of the text and writes a 'this is a run of the same mark' signal:
  * a dot or asterisk that repeats the token just before it (". . . ." or "* * *")
    gives a large positive value (~4.4);
  * a bullet, or a rule-line mark, repeated (+\\n, `, <) gives a small value (~1);
  * a period that ends a single-letter initial which itself follows a period
    (the second initial of a name, as in "E. L[.] Voyn") gives a moderate value;
  * a run of middle dots "··" gives a strong negative value.
Everything else predicts 0. Repeats count only within one document.
"""
READS = ()

BIG_RUN = {" .", " *", "*\\", "•"}
SMALL_RUN = {"+\n", " `", "<\n"}


def is_initial(text):
    core = text.strip()
    return len(core) == 1 and core.isupper()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    cur = toks[-1]
    value = 0.0
    if cur == "··":
        value = -3.5
    elif len(toks) >= 2 and docs[-2] == docs[-1]:
        prev = toks[-2]
        if cur == prev and cur in BIG_RUN:
            value = 4.4
        elif cur == prev and cur in SMALL_RUN:
            value = 1.0
        elif cur == "." and is_initial(prev) and len(toks) >= 3 and docs[-3] == docs[-1] and toks[-3] == ".":
            value = 1.7
    return carry, value

programs.sol:
"""Recognize unfinished UTF-8 characters and visible formatting fragments.

A token that ends partway through a character usually gets a negative value,
especially if it is just continuation bytes. Ordinary completed characters get
almost zero. Other negative cases are within-line padding, double underscores,
web-domain endings, and the closing reasoning marker; doubled middle dots are
positive. Indentation and bare comment/table borders are not within-line padding.
Physical and backslash-escaped newlines both reset the line context.
These rounded rules omit ordinary word-specific activation fluctuations.
"""
import codecs
import re
import regex

READS = ()
DOMAIN_ENDINGS = {
    '.com', '.org', '.net', '.edu', '.gov', '.mil', '.int',
    '.io', '.de', '.uk', '.cn', '.jp', '.fr', '.ru', '.ca', '.au',
    '.tw', '.ch', '.it', '.nl', '.es', '.info', '.biz', '.co',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pending, line = b'', ''
    else:
        _, pending, line = carry
    b = prefix.token_bytes[-1]
    s = prefix.token_strings[-1]
    _, used = codecs.utf_8_decode(pending + b, 'replace', False)
    pending = (pending + b)[used:]
    value = -0.002
    if pending:
        # Complete the unfinished character with minimal continuation bytes
        # solely to identify its script, not to guess the intended character.
        representative = (pending + b'\x80' * 3).decode('utf8', 'ignore')[:1]
        han = bool(regex.match(r'\p{Script=Han}', representative))
        hangul = bool(regex.match(r'\p{Script=Hangul}', representative))
        hiragana = bool(regex.match(r'\p{Script=Hiragana}', representative))
        katakana = bool(regex.match(r'\p{Script=Katakana}', representative))
        greek = bool(regex.match(r'\p{Script=Greek}', representative))
        if all(128 <= c < 192 for c in b):
            value = -2.88 if greek else (-2.0 if len(pending) == 3 else -1.65)
        elif b.startswith(b' '):
            if hangul:
                value = -0.8 if len(pending) == 1 else -0.93
            elif katakana:
                value = 0.0
            elif hiragana:
                value = -0.39
            elif len(pending) == 3:
                value = -1.2
            elif len(pending) == 1 and not (han or greek):
                value = -0.3
            else:
                value = -0.5
        else:
            if hiragana or katakana:
                value = 0.0
            elif hangul:
                value = -0.45
            else:
                value = -0.9 if han else -0.7
    elif s and s.strip(' ') == '' and len(s) > 1:
        if line.strip(' \t/*#|─━-+║│'):
            # Alignment after a word is stronger than after a number or border.
            last = line.rstrip()[-1:]
            if last.isalpha():
                value = -0.9 if len(s) < 4 else -1.3
            elif last == ':':
                value = -1.1
            else:
                value = -0.45 if len(s) < 4 else -0.6
        else:
            value = -0.02
    elif s and s.isspace() and '\xa0' in s:
        value = -0.19
    elif s == '__':
        value = -1.04
    elif '__' in s:
        value = -0.23
    elif s in DOMAIN_ENDINGS:
        value = -0.55
    elif s == '</think>':
        value = -0.45
    elif s == '<|im_end|>':
        value = 0.14
    elif s == '··':
        value = 1.9
    # Code embedded in JSON often spells its newlines as backslash-n.
    line = re.split(r'[\r\n]|\\[nr]', line + s)[-1][-150:]
    return (doc, pending, line), value

programs.haiku:
"""Layer 1 MLP down_proj component 3590: a negative "broken text / layout noise" detector.

Mostly silent (about 0) on ordinary words and punctuation. It goes negative on a few
kinds of token that look like text-formatting noise:

* a replacement character U+FFFD, which a token shows when it holds only part of a
  multi-byte UTF-8 character (mis-decoded or mixed-script text). Strongest on the first
  such token of a run; weaker on the rest of the run;
* a run of underscores such as "__" (identifiers, dunders, paths);
* a carriage return "\\r" (Windows line endings);
* a long run of spaces or non-breaking spaces (indentation or layout padding);
* web-address suffixes (".com", ".org", ...) and the closing "</think>" tag.

A document's first token gets a small positive value. Everything else gets 0. The
values are rough class averages from training text.
"""

READS = ()

WEB_SUFFIXES = {".com", ".org", ".io", ".uk", ".net", ".edu", "</think>"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if "�" in s:
        value = -0.25 if "�" in prev else -0.6
    elif s and set(s) == {"_"}:
        value = -0.9
    elif s == "\r":
        value = -0.4
    elif len(s) >= 5 and set(s) <= {" ", "\xa0"}:
        value = -0.2
    elif len(s) >= 2 and set(s) <= {" ", "\xa0"}:
        value = -0.05
    elif s in WEB_SUFFIXES:
        value = -0.4
    elif len(prefix.token_ids) == 1:
        value = 0.1
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A pulse at code-comment openers, strongest after indentation.

Recognize //, /*, #, -- and % as comment punctuation.  Distinguish indented
comments from trailing comments, headings, and delimiters that already contain
a newline.  Escaped whitespace in quoted source counts as indentation too.
Document beginnings have a weak negative bias, strongest for unspaced capitalized
ASCII tokens. Middle-dot runs are negative too. Other text is quiet.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    line, previous = ('', '') if fresh else carry[1:]
    token = prefix.token_strings[-1]
    s = token.lstrip(' \t')
    leading = len(s) < len(token)
    normalized = line.replace('\\t', '\t').replace('\\r', '\r')
    start = re.fullmatch(r'\s*(?:\d+[ \t]+)?[+\-]?\s*', normalized) is not None
    escaped_space = previous.endswith(('\\n', '\\t'))
    previous_indent = bool(previous) and previous.isspace() and '\n' not in previous
    quoted_code = previous.strip() in ('`', '``')
    newline = '\n' in s
    value = 0.0

    if s.rstrip() == '//':
        if newline:
            value = 0.05
        elif escaped_space or quoted_code:
            value = 1.25
        elif leading:
            value = 1.0 if previous_indent else 0.44
        else:
            value = 0.9 if previous_indent else 0.75
        if fresh and not newline:
            value = -0.5 if leading else -0.85
    elif s.startswith('///'):
        value = 0.06 if newline else 0.45
    elif s.startswith('/*'):
        if s.startswith('/**') or newline:
            value = 0.61
        else:
            value = 0.76 if start else 0.43
    elif s == '#':
        if fresh:
            value = 0.10
        elif escaped_space:
            value = 1.20
        elif quoted_code:
            value = 1.05
        elif previous_indent:
            value = 0.88 if leading else 0.75
        elif leading:
            value = 0.55 if start else 0.14
        elif previous.endswith('\n'):
            end = previous.rstrip()
            if end and end[-1] in ');}]':
                value = 0.96
            elif end and end[-1] in '.?!':
                value = 0.15
            else:
                value = 0.28 if '\n\n' in previous else 0.47
    elif s and set(s) == {'#'}:
        value = 0.13 if len(s) == 2 else 0.04
        if len(s) >= 6:
            value = 0.35
    elif s == '--':
        value = 0.85 if start else -0.06
    elif s and set(s.rstrip()) == {'-'} and len(s.rstrip()) >= 4:
        value = 0.22 if start else -0.05
    elif s == '%':
        value = 1.0 if start and not fresh else 0.04
    elif len(s) >= 2 and set(s) == {'·'}:
        value = -1.0

    if fresh and value == 0.0:
        if token.isascii() and token[:1].isupper():
            value = -0.30
        elif any(c.isalnum() for c in token):
            value = -0.13
        else:
            value = -0.05

    line = re.split(r'\n|\\n', line + token)[-1][-160:]
    return (doc, line, token), value

programs.haiku:
"""Comment-opener detector: predicts a comment's opening token (//, #, /*, /**, ///, --, ##)
with a typical strength per comment style, and a negative value on each document's first token."""

READS = ()

COMMENT_OPENERS = {"//": 0.8, "#": 0.55, "/*": 0.7, "/**": 0.6, "///": 0.35, "--": 0.15, "##": 0.1}
DOC_START_VALUE = -0.17


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, DOC_START_VALUE
    return None, COMMENT_OPENERS.get(token, 0.0)

programs.sol:
"""A mixture of spelling and mental-imagery cues.

Negative peaks mark gin-like fragments, including a g followed by a separate
in/un/yn suffix. Some sin/cin continuations have the opposite sign. Frequent
English words weaken this fragment reading. Mental verbs and 'think of' have
separate negative estimates, strengthened by ability modals or prompt syntax.
CamelCase starts and Turkish soft g are not hard-g suffix cues.
Other tokens predict zero; document boundaries reset the short text memory.
"""
import re
from functools import lru_cache
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=16384)
def frequent(word):
    return len(word) > 3 and zipf_frequency(word.lower(), 'en') >= 3.0


def response(prior, previous, raw):
    word = raw.strip().lower()
    if word in {'imagine', 'consider', 'understand', 'see', 'of', 'about'}:
        ability = bool(re.search(
            r"\b(?:can|could|cannot|can't|couldn't)\b[^.!?\n]{0,18}$",
            prior.lower()))
        if word == 'imagine':
            if ability:
                return -5.9
            if raw.strip()[0].isupper():
                return -4.8
            return -1.7 if re.search(r'\bI\s*$', prior) else -3.3
        if word == 'consider':
            prompt = raw.strip()[0].isupper() or re.search(
                r'(?:,|\bme)\s*$', prior)
            return -1.1 if prompt else -0.38
        if word == 'understand':
            return -1.2 if ability else -0.15
        if word == 'see':
            return -0.68 if ability else -0.015
        if re.search(r'\b(?:think|thinking|thought)\s*$', prior, re.I):
            prompt = ability or re.search(r'\bThink\s*$', prior)
            if word == 'of':
                return -4.5 if re.search(r'\bThink\s*$', prior) else (
                    -3.2 if prompt else -1.8)
            return -0.25 if prompt else -0.14
    if word in {'imagined', 'imaginary', 'virgin'}:
        return {'imagined': -1.7, 'imaginary': -0.85, 'virgin': -3.9}[word]
    if word == 'mind' and re.search(r'\bin\s*$', prior, re.I):
        return -0.34
    if word == 'imagin':
        return -5.0
    if re.fullmatch(r'(?:[aiou]|ar)?gin[ae]?', word):
        if raw.strip().isupper() or raw[0].isspace():
            return -3.2
        if word == 'agine' and prior.lower().endswith('/im'):
            return -7.0
        return -6.4 if word.startswith('ag') else -5.0

    # Interpret alphabetic subword pieces, not arbitrary transliterated text.
    if not raw.isascii() and not regex.fullmatch(
            r'[\p{Latin}\p{Cyrillic}\p{Greek}]+', raw):
        return 0.0
    # A capital letter starts a new CamelCase word, not a suffix.
    if raw[:1].isupper() and not raw.isupper():
        return 0.0
    s = anyascii(raw).lower()
    if frequent(s):
        return 0.0
    # Turkish soft g is not a hard-g spelling cue.
    tail = prior[-5:].replace('ğ', '').replace('Ğ', '')
    before = anyascii(tail).lower()
    scale = 0.5 if frequent(previous.strip()) else 1.0
    if re.match(r'lin(?![gkqcfh])', s):
        return scale * {'g': -2.8, 's': 0.9}.get(before[-1:], 0.0)
    m = re.match(r'([iuy])n(?![gkqcfh])', s)
    if m:
        vowel, consonant, long = m[1], before[-1:], len(s) > 3
        if before.endswith('gu') and vowel == 'i':
            return -2.3
    elif re.match(r'n(?![gkqcfh])', s) and len(before) >= 2:
        vowel, consonant, long = before[-1], before[-2], len(s) > 2
    else:
        return 0.0
    if vowel == 'i':
        if s in ('ina', 'ino') and consonant in ('s', 'c'):
            return scale * (2.5 if consonant == 's' else 1.9)
        short_long = {'g': (-4.2, -2.6), 's': (1.1, 0.8),
                      'c': (0.75, 0.4), 'z': (0.2, 0.2)}
        return scale * short_long.get(consonant, (0.0, 0.0))[long]
    if consonant == 'g' and vowel == 'u':
        if s.startswith('und') or any(ch in raw for ch in 'úüÚÜ'):
            return -0.5 * scale
        return scale * (-2.0 if long else -3.1)
    if consonant == 'g' and vowel == 'y':
        return scale * (-1.0 if long else -2.4)
    if not long:
        return scale * {('s', 'y'): 0.35, ('z', 'y'): 0.3,
                        ('c', 'y'): 0.15, ('c', 'u'): 0.2}.get(
                            (consonant, vowel), 0.0)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prior, previous = carry[1:] if carry and carry[0] == doc else ('', '')
    raw = prefix.token_strings[-1]
    value = response(prior, previous, raw)
    return (doc, (prior + raw)[-96:], raw), value

"""A partial approximation using document openings and local expressions.

Observed large responses often fall on an expression's second token.
These rules recognize selected color, numeral, water/blood, and Chinese
thunder-prefixed expressions, plus title and source-code openings.
Everything else gets a background estimate, adjusted at document starts
for a leading space or a digit. Most activation variation is not modeled.
"""

READS = ()
COLORS = {'black', 'white', 'red', 'blue', 'green', 'yellow',
          'orange', 'purple', 'pink', 'brown', 'gray', 'grey'}
SOURCE_OPENERS = {'package': -1.55, 'import': -1.11, 'from': -1.01,
                  'def': 0.98, 'var': -1.0}
SIX_UNITS = {'feet', 'foot', 'inch', 'inches', 'month', 'months',
             'year', 'years', 'members'}


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        previous, position = carry[1], carry[2] + 1
    old = previous.strip().lower()
    word = text.strip().lower()
    value = 0.002

    if position == 0:
        # A word-boundary or a digit also shifts the opening baseline.
        if text.startswith(' '):
            value = 0.15
        elif text.isdigit():
            value = 0.13
        if text == '//\n':
            value = -3.98
        elif text == '//':
            value = -0.99
        else:
            value = SOURCE_OPENERS.get(text, value)
    elif position == 1 and previous == 'Title' and text == ':':
        value = -4.235
    elif old in COLORS and word in {'flag', 'flags'}:
        value = 3.2
        if old in {'black', 'yellow'}:
            value = 3.9
    elif old == 'water':
        if word in {'vapor', 'vapour', 'molecule', 'molecules'}:
            value = -1.05
        elif word in {'surface', 'surfaces', 'level', 'levels'}:
            value = -0.5
    elif old == 'blood':
        if word == 'flow':
            value = -1.0
        elif word in {'stain', 'stains'}:
            value = -0.45
    elif old == 'black':
        if word == 'market':
            value = 3.0
        elif word == 'ink':
            value = -1.1
        elif word in {'marker', 'smoke'}:
            value = 1.4
        elif word in {'hole', 'holes'}:
            value = -0.5
    elif old == 'white':
        if word in {'shark', 'sharks'}:
            value = 1.2
        elif word == 'blood':
            value = -0.65
        elif word == 'noise':
            value = 0.67
    elif old in {'six', '6'} and word in SIX_UNITS:
        value = 0.3
    elif old == 'sixth':
        if word in {'grade', 'grad'}:
            value = 1.0
        elif word == 'form':
            value = 6.5
    elif old == 'art' and word == 'form':
        value = 1.9
    # Chinese fractions are expressed in tenths with 成.
    elif text == '成' and previous in {'四', '六', '八'}:
        value = {'四': 1.2, '六': 5.5, '八': 4.0}[previous]
    elif previous == '雷' and text in {'射', '打', '暴'}:
        value = 1.7
    elif previous == '水' and text == '下':
        value = -2.0
    elif previous == '血' and text == '迹':
        value = -3.3
    return (doc, text, position), value

