"""Component layers.1.mlp.down_proj:3594 (layer 1 MLP output, direction 3594).

Plain-terms summary: this component is almost always near zero. Most of its
variance is idiosyncratic, token-by-token, so no short rule captures it. Three
readable patterns carry the part that a short program can explain:

1. The first token of a document (documents are packed end to end after
   <|endoftext|>, and the model restarts at each one):
   - if it opens a source or markup file (package, import, from, #include-style
     "#", "//", "<!", "<", "/*", "__", "use", "const", "require"), the value is
     clearly negative;
   - if it is a capitalised word, slightly negative;
   - if it is a lower-case fragment, a space or a digit, slightly positive;
   - anything else, slightly positive.
2. A metadata header "Title:" at the very start of a document (the colon right
   after a document-initial "Title"): strongly negative.
3. Mid-document, the character right after the Chinese numeral 六 ("six", as in
   六成, "sixty percent", or 六爻, an I Ching line): positive. After 七 or 八 it
   is weakly positive.

Everywhere else the value is 0, which is close to the component's typical
(near-zero) activation.
"""
READS = ()

CODE_OPENERS = {"package", "import", "from", "use", "const", "require", "//", "//\n",
                "/*", "<!", "<", "#", "__"}
EOT = "<|endoftext|>"


def _is_upper(s):
    return s.strip()[:1].isupper()


def _is_lower(s):
    c = s.strip()
    return c[:1].islower() or s[:1] == " " or s[:1].isdigit()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    n = len(prefix.token_ids)
    new_doc = n == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        if tok in CODE_OPENERS:
            return None, -0.8
        if _is_upper(tok):
            return None, -0.05
        if _is_lower(tok):
            return None, 0.15
        return None, 0.05
    prev = prefix.token_strings[-2]
    if tok == ":" and prev == "Title" and n >= 3 and prefix.token_strings[-3] == EOT:
        return None, -4.0
    if prev == "六":
        return None, 0.75
    if prev in {"七", "八"}:
        return None, 0.25
    return None, 0.0

programs.sol:
"""A conservative detector for short e-ending spelling continuations.

Track the unfinished ASCII word. Predict positive pulses when a short
continuation adds e (optionally followed by s or y) after a vowel digraph
or an r-controlled consonant ending, as in Browne, Brooke, and Clarke.
Give doubled consonants small pulses and -sle/-tle/-kle small negatives.
Scale all pulses by 0.6: these spelling rules only partially explain the
component, and are not a pronunciation or word-meaning analysis.
"""
import re

READS = ()
VOWEL_END = re.compile(
    r'(ai|au|aw|ay|ea|ee|ei|eu|ew|ey|ie|oa|oe|oi|oo|ou|ow|oy|ue|ui|uy|'
    r'[aeiouy])([bcdfghjklmnpqrstvwxyz]*)$'
)
LONG_VOWELS = {'ai', 'au', 'aw', 'ay', 'ea', 'ee', 'ei', 'eu', 'ew',
               'ey', 'oa', 'oe', 'oi', 'oo', 'ou', 'ow', 'oy'}


def ending_response(word, token):
    if not (word and token.isascii() and token.isalpha() and len(token) <= 4):
        return 0.0
    token = token.lower()
    j = token.rfind('e')
    if j < 0 or token[j + 1:] not in ('', 's', 'y'):
        return 0.0
    beginning = token[:j]
    # A whole syllable already inside one piece usually needs no pulse.
    if re.search(r'[bcdfghjklmnpqrstvwxz][aeiouy]', beginning):
        return 0.0
    match = VOWEL_END.search(word.lower() + beginning)
    if match is None:
        return 0.0
    vowel, consonants = match.groups()
    in_stem = match.start() < len(word)
    before_piece = match.start() + len(vowel) <= len(word)
    long_vowel = vowel in LONG_VOWELS
    ordinary_soft_ending = consonants[-1:] in ('c', 'g', 's', 'v', 'z', 'h')

    # A digraph before a single final consonant: Brown-e, Brook-e, etc.
    if long_vowel and len(consonants) <= 1 and not ordinary_soft_ending:
        if not in_stem:
            return 1.0 if consonants == 'n' else 0.15
        if vowel == 'ow':
            return 5.7 if beginning else 3.0
        if vowel == 'oo':
            return 3.2
        if consonants == 'k':
            return 2.2
        if vowel == 'ea' and consonants:
            return 1.6
        return 0.65 if before_piece else 0.2

    # E after an r-controlled closed syllable, especially -rke and -rpe.
    if in_stem and consonants in ('rk', 'rn', 'rp', 'rt', 'rd', 'rm', 'rb', 'rl'):
        if consonants == 'rk':
            if vowel == 'e':
                return 0.4
            if token[j + 1:]:
                return 0.9
            return 4.8 if vowel == 'u' else 3.1
        if long_vowel:
            return 1.9
        if consonants == 'rp':
            return 2.2
        return 0.6 if consonants == 'rn' else 0.1

    if len(consonants) == 2 and consonants[0] == consonants[1]:
        return 0.0 if ordinary_soft_ending else 0.15
    if consonants.endswith(('sl', 'tl', 'kl')):
        return -0.25
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    value = 0.6 * ending_response(previous, token)
    tail = re.search(r'[A-Za-z]+$', token)
    if tail is None:
        word = ''
    elif tail.start() == 0:
        word = (previous + token)[-40:]
    else:
        word = tail[0][-40:]
    return (document, word), value

"""Spelling-sensitive inter- detector, including split word pieces.

Interest, interfaces and interference are negative; interconnection pieces
are positive. Split stems often respond much more strongly than whole words.
An interface following a code declaration keyword is especially negative.
French accented stems, Cyrillic интер-, and a few 互 compounds have analogous
rules. All other text is nearly zero. State is only recent text and a word tail.
"""
import re
import unicodedata
from functools import lru_cache

READS = ()

# Each row: word-family spelling, whole token, first suffix, later suffix.
# Suffix means a token joined onto an already-started word.
# First suffix: immediately after the short spelling int/inte/inter.
FAMILIES = (
    (r'intercon(?:nect|nection)', 2.8, 5.8, 4.5),
    (r'intermin', 0.1, 6.0, 0.2),
    (r'inter(?:con|rel|link|com|red|ment)', 2.8, 4.3, 1.2),
    (r'interference', -2.2, -5.2, -2.0),
    (r'interfer', -1.1, -5.2, -2.0),
    (r'inter(?:est$|ess$|es$|et$)', -2.0, -2.9, -1.5),
    (r'intere(?:s|t|$)', -0.5, -3.0, -0.5),
    (r'interaction', -0.3, -0.8, -0.8),
    (r'interactiv', -1.4, -2.8, -2.0),
    (r'intera[ck]t', -0.7, -3.7, -2.1),
    (r'interview', -0.15, -1.0, -0.5),
    (r'interv', -1.2, -4.5, -1.5),
    (r'inter(?:st$|sti|stell|gal|gr)', -0.1, -5.0, -2.5),
    (r'inter(?:pol|oper|pret|rog|cost|met)', -0.3, -1.8, -0.8),
    (r'interior', 0.5, 1.1, 0.4),
    (r'inert', -0.5, -3.3, -1.2),
    (r'intellig|intelig', -0.3, -1.4, -0.7),
)


@lru_cache(maxsize=8192)
def normalize(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


def predict(token, before, previous, recent):
    s = normalize(token)
    part_match = re.search(r'[^\W\d_]+$', s)
    part = part_match.group() if part_match else ''
    # Keep inter- productive across hyphenation and CamelCase identifiers.
    if previous.endswith('Inter'):
        before = 'inter'
    joined = bool(s and s[0].isalpha() and before)
    if before == 'inter' and s.startswith('-'):
        joined, s = True, s[1:]
    match = re.search(r'[^\W\d_]+$', before + s if joined else s)
    word = match.group() if match else ''
    if part.startswith(('inter', 'интер')):
        word, joined = part, False
    split = joined and before.startswith(('int', 'инт'))
    first = split and before in ('int', 'inte', 'inter', 'инт', 'инте', 'интер')

    if token == '··':
        return word, -0.87
    if previous.endswith(('互动', '交互', '互動')):
        return word, -1.5 if token.startswith(('式', '性')) else 0.0
    if previous.endswith('互'):
        if token.startswith(('连', '联', '連', '聯', 'い')):
            return word, 5.5
        if token.startswith('关联'):
            return word, 2.8
        return word, 0.15 if previous.endswith('相互') else 0.6
    # Chinese: financial interest, interface, and intervention.
    if token in ('利息', '界面', '干预'):
        return word, {'利息': -3.3, '界面': -0.8, '干预': -1.1}[token]
    if before == 're' and token == '-int':
        return word, 2.5
    if before == 'inter' and token.strip() == 'al':  # inter alia
        return word, -4.5

    if word.startswith('интер'):
        if word.startswith('интерф'):
            return word, -5.3 if part.startswith('еи') else -4.0
        if word.startswith('интерес'):
            return word, -0.3 if split else -2.6
        if word.startswith('интерв'):
            return word, 1.0 if 'ью' in word else -2.7
        return word, -0.5

    if word == 'interf' or word.startswith('interfaci'):
        return word, -5.0
    if word.startswith('interfac'):
        if split:
            return word, -6.5 if first else -2.0
        if token.startswith('_'):
            return word, -0.8
        p = previous.strip().lower()
        if p.endswith('export'):
            return word, -7.3
        if p == 'public':
            return word, -4.8
        if previous.endswith('\n'):
            return word, -4.5
        code = any(c in recent[-24:] for c in '{}();=')
        return word, -2.2 if code else -1.5
    if word.startswith('integr') and split:
        if before == 'inte' and part == 'gr':
            return word, -4.3
        if before == 'integr' and part in ('er', 'ation', 'al', 'ante'):
            return word, {'er': -2.2, 'ation': -2.2,
                          'al': -4.0, 'ante': 3.3}[part]
        return word, -1.1 if len(before) < 6 else -0.2
    if before == 'inte' and part.startswith('ress'):
        return word, -6.0
    if before == 'inter' and part == 'ventional':
        return word, -12.0
    if not word.startswith(('inter', 'inert', 'intellig', 'intelig')):
        return word, -0.001
    for pattern, whole, initial, later in FAMILIES:
        if re.match(pattern, word):
            return word, initial if first else later if split else whole
    if word == 'inter':
        return word, -0.28
    if word.startswith('inter'):
        return word, -1.0 if split else -0.15
    return word, -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before = previous = recent = ''
    else:
        _, before, previous, recent = carry
    token = prefix.token_strings[-1]
    word, value = predict(token, before, previous, recent)
    return (doc, word[-40:], token, (recent + token)[-80:]), float(value)

"""A sparse text approximation of reply/discussion activation.

It recognizes answer labels, forum roles, dated comment boundaries, direct
address, and tentative restarts of a solution. It also models thought-tag
whitespace and several negative document-opening conventions. Only the last
600 characters of the current document are retained; detailed contextual
variation and most multilingual labels are not reproduced.
"""
import re

READS = ()
SECOND = {'you', 'your', 'yours', 'yourself', 'yourselves'}
MODALS = {'can', 'could', 'would', 'should', 'will', 'may', 'might', 'shall', 'must'}
HEDGES = {'perhaps', 'maybe', 'probably', 'possibly', 'presumably', 'apparently'}
ROLES = {'member', 'staff', 'mentor', 'helper', 'moderator', 'administrator',
         'director', 'expert', 'supporter', 'contributor', 'instructor'}
ANSWERS = {'answer', 'answers', 'reply', 'replies', 'response', 'responses'}
# Completions of recognizable discussion labels, not arbitrary token IDs.
LABELS = {
    'originally posted': 2.15,
    'last edited': 1.97,
    'homework helper': 4.20,
    'staff: mentor': 5.85,
    'staff emeritus': 3.56,
    'gold member': 1.86,
    'share on other sites': 1.96,
    'expert comment': 0.74,
    'author comment': 0.74,
    'thread starter': -1.30,
}
MONTH = r'(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    past, pos = ('', 0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    text = past + token
    line = past.rsplit('\n', 1)[-1]
    words = re.findall(r'[A-Za-z]+', past[-80:])
    prev = words[-1].lower() if words else ''
    line_start = not line.strip(' #*\t-')
    start = pos == 0 or line_start or bool(re.search(r'[.!?]\s*$', past))
    upper = token.lstrip()[:1].isupper()
    value = 0.0
    if word in SECOND:
        value = -0.01 if word == 'your' else 0.02
        value += 0.05 * start - 0.12 * (prev in MODALS) - 0.07 * (prev == 'do')
        value += 0.11 * (prev == 'if') + 0.08 * (prev == 'are')
        value += 0.45 * bool(re.search(r'\n\n(?:[A-Za-z]+[ ,]*){0,2}$', past))
        value += 0.04 * ('?' in past[-150:])
        if re.search(r'(?i)(?:\bre:|originally posted|\bposts:|\bjoined:)', past):
            value += 0.49
        forum_role = r'(?i)(?:super user|homework helper|author comment|'
        forum_role += r'expert comment|\banswered|\banswer by)'
        if re.search(forum_role, past):
            value += 0.44
        assistant = past.rfind('<|im_start|>assistant')
        value += 0.04 * (assistant > past.rfind('<|im_start|>user'))
    if word in HEDGES:
        value += 0.01 + 0.18 * start
    if word == 'perhaps':
        value += 0.14 + 0.37 * upper
    if word == 'wait' and start:
        value += 0.19
    if word in {'hi', 'hello'} and start:
        value += 0.66 if word == 'hi' else 0.32
    if word == 'try' and re.search(r'(?i)\blet\s+me\s*$', past):
        value += 0.25
    if word in {"'s", '’s'} and prev == 'let':
        value += 0.40
    if (word in {'approach', 'way', 'method'}
            and prev in {'another', 'different', 'other'}):
        value += 1.04
    if (word in {'stated', 'intended', 'expects', 'wants'}
            and re.search(r'(?i)\bproblem\b', past[-60:])):
        value += 0.89
    if word == 'mean' and prev == 'you':
        value += 1.76
    if word in ANSWERS:
        value += 0.09 + 0.09 * upper + 1.41 * line.strip().startswith('#')
    if token.strip() == 'OP':
        value += 0.30
    lower_text = text.lower()
    for label, weight in LABELS.items():
        if lower_text.endswith(label):
            value += weight
    if token.startswith(':'):
        value += 1.40 * bool(re.search(r'(?:^|\s)Re$', past))
        value += 1.10 * bool(re.search(r'(?:^|\n)A$', past))
    if word in ROLES and (line_start or prev in {
            'homework', 'forum', 'staff', 'gold', 'gmat'}):
        value += 0.47
    if word == 'staff' and line_start:
        value += 0.29 + 5.00 * (line.strip() == '###')
    if text.endswith('\nLVL'):
        value += 2.81
    if word == 'edit' and start:
        value += 0.40

    at_date = word == 'at' and re.search(
        '(?i)' + MONTH + r'\s+\d[^\n]{0,20}$', past)
    end_time = '\n' in token and re.search(
        '(?i)' + MONTH + r'\s+\d[^\n]{0,40}\d:\d{2}\s*$', past)
    signature = '–' in line or '—' in line or bool(re.search(r" '\d{2}\b", line))
    value += (0.29 + 1.65 * signature) * bool(at_date)
    value += (0.59 + 1.78 * signature) * bool(end_time)
    if token.startswith('-\n') and past.endswith('\n\n'):
        value += 3.50
    if word in {'•', '●'}:
        value += 0.10 + 0.12 * ('?' in past[-300:])
        value += 1.49 * bool(re.search(r'\d:\d{2}\s*$', past))
    if word and set(word) == {'·'}:
        value -= 0.45

    value += {'<think>': 0.13, '</think>': 0.04, '<|im_end|>': -0.04}.get(token, 0)
    if token.isspace():
        value += 0.12 * past.endswith('<think>') + 0.28 * past.endswith('</think>')
        value += 0.08 * bool(re.search(r'<think>\s*</think>$', past))
        role_end = r'<\|im_start\|>(?:assistant|user|system)$'
        value -= 0.03 * bool(re.search(role_end, past))
