                 "'''\n": -1.36, '<|endoftext|>': -1.92}.get(token, value)
    if pos == 1 and past == 'Title' and token == ':':
        value = -3.73
    if token == '\r' and not past.strip('\r'):
        value = -2.55
    return (doc, text[-600:], pos + 1), float(value)

