"""Forum user-rank and thread-metadata detector (layers.1.mlp.down_proj:3598).

The component is near zero on most text. Its large activations come from web-forum
metadata:
- a user's rank or role word on its own line, strongest after a forum header
  ("### Staff: Mentor", "Homework Helper", "Gold Member");
- "Posted" in "Originally Posted by";
- the "at" of a comment timestamp ("Nov 19 '19 at 1:37").
A weaker, diffuse response goes to talk about an answer ("answer", "perhaps", "wait")
and, very slightly, to "you".
A colon right after a reply label ("### Re:", "A:") also fires.
Role words inside code (IOHelper, Helper.java) and in running prose are near zero.
Each case gets a fixed value near its typical activation. Everything else is 0.
The program looks back at most 8 tokens, within the same document.
"""

READS = ()

ROLE_WORDS = {"Staff", "Mentor", "Helper", "Member", "Admin", "Moderator", "Expert"}
FORUM_CUES = {"###", "Homework", "Gold", "Posted", "Originally", "Share", "Replies", "Edit"}
MONTHS = {"Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"}
TALK = {"answer", "perhaps", "Perhaps", "wait", "Wait", "Edit"}
YOU = {"you", "You"}


def step(carry, prefix, upstream):
    t = prefix.position
    doc = prefix.document_ids
    recent = []
    i = t - 1
    while i >= 0 and i >= t - 8 and doc[i] == doc[t]:
        recent.append(prefix.token_strings[i])
        i -= 1
    tok = prefix.token_strings[t].strip()
    cues = {c.strip() for c in recent}
    line_start = t == 0 or not recent or "\n" in recent[0]
    if tok in ROLE_WORDS and cues & FORUM_CUES:
        return carry, 5.0
    if tok in ROLE_WORDS and line_start:
        return carry, 1.5
    if tok == "Posted" and "Originally" in cues:
        return carry, 2.5
    if tok == "at" and any(c.strip() in MONTHS or c.strip().startswith("'") for c in recent):
        return carry, 0.3
    if tok == ":" and recent and recent[0].strip() in {"Re", "A"}:
        return carry, 1.2
    if tok in TALK:
        return carry, 0.3
    if tok in YOU:
        return carry, 0.07
    return carry, 0.0

programs.sol:
"""Approximate the prominent 'as' response using spelling and short context.

The response is weaker in 'such as', 'known as', equality/definition phrases,
import aliases, and short 'as ... as' comparisons. Case, word boundaries,
and an estimated Portuguese context adjust the pulse. A secondary response
marks the colon in a document-initial 'Title:' header. Retain a short
text tail, resetting it at each new document. Other spellings predict zero;
their diffuse token-specific activity is deliberately left unexplained.
"""
import re
import wordnet
from wordfreq import zipf_frequency

READS = ()


def as_value(token, tail):
    word = token.strip()
    if not tail:
        if word == 'as':
            return -0.33 if token.startswith(' ') else 0.24
        return 0.83 if token.startswith(' ') else 0.45
    boundary = token[:1].isspace() or not tail[-1].isalnum()
    if not boundary:
        return 0.25 if word == 'AS' else 0.1
    if word == 'AS':
        return 0.55
    if word == 'As':
        return 0.53 if re.search(r'\b(?:a|an|the)\s*$', tail) else 0.83

    words = re.findall(r'[^\W\d_]+', tail.lower())
    prev = words[-1] if words else ''
    recent = ' '.join(words[-4:])
    if prev == 'such':
        return 0.03
    if re.search(r'\bsuch(?: \w+){1,2}$', recent):
        return 0.5
    if prev == 'well':
        return 0.05
    if re.search(r'\bsame(?: \w+){0,3}$', recent):
        return 0.33
    if prev == 'known' or recent.endswith('referred to'):
        return 0.12
    if prev in {'serve', 'serves', 'served', 'serving'}:
        return 0.67
    if prev in {'defined', 'written', 'expressed', 'represented', 'interpreted'}:
        return 0.68
    if prev in {'so', 'just'}:
        return 0.7
    if re.search(r'\bimport\s+(?:\*|[.\w]+)\s*$', tail):
        return 0.03

    clause = re.split(r'[.!?;:\n]', tail.lower())[-1]
    match = re.search(r'\bas\s+((?:\w+\s+){0,2}\w+)\s*$', clause)
    if match:
        first = match[1].split()[0]
        if wordnet.parts_of_speech(first) & {'adjective', 'adverb'}:
            return -0.22

    context = words[-6:]
    english = sum(zipf_frequency(w, 'en') for w in context)
    portuguese = sum(zipf_frequency(w, 'pt') for w in context)
    return 0.27 if portuguese > english + 5 else 1.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    match = re.fullmatch(r'([\W_]*)(as)', token, re.I)
    if match:
        punctuation = match[1].strip()
        form = (' ' if punctuation else match[1]) + match[2]
        value = as_value(form, tail.replace('\\n', '\n'))
        if punctuation:
            value *= 0.9
    elif token == 'nas' and tail.endswith('\\'):
        # A literal escaped newline can share its final token with 'as'.
        value = as_value('as', tail[:-1] + '\n')
    elif token == ':' and tail == 'Title':
        value = 2.67
    return (doc, (tail + token)[-180:]), value

"""A local grammar detector for 'part' and the following 'of'.

Membership phrases ('as part', 'is part') are strongly negative. Articles,
possession, spatial modifiers and other adjectives weaken or reverse this.
Word fragments are joined so, for example, 'dist' + 'al' is one modifier,
while the 'part' inside 'aspartic' is not mistaken for 'as part'. Smaller
rules cover plural 'parts', Romance 'parte', 'as per', 'as of', and
'part and parcel'. Other tokens get zero. State resets at document changes.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
COPULAS = {'is', 'are', 'was', 'were', 'be', 'been', 'being'}
CHANGE = {'become', 'becomes', 'became', 'becoming', 'form', 'forms'}
CONTRACTIONS = {"it's", "he's", "she's", "that's", "there's", "what's",
                "who's", "i'm", "we're", "they're", "you're"}
POSSESSIVES = {'his', 'her', 'their', 'our', 'its', 'your', 'my'}
DETERMINERS = POSSESSIVES | {'the', 'a', 'an', 'this', 'that', 'any', 'some'}
SPATIAL = {'upper', 'lower', 'central', 'top', 'bottom', 'center', 'middle',
           'uppermost', 'lowermost', 'innermost', 'outermost',
           'anterior', 'posterior'}


@lru_cache(maxsize=2048)
def tags(word):
    return wordnet.parts_of_speech(word)


def responses(tail):
    """Return the response at 'part', then at a following 'of'."""
    tail = tail.rstrip().lower().replace('’', "'")
    if tail and tail[-1].isdigit():
        return -0.5, -2.0
    if not tail or not ('a' <= tail[-1] <= 'z'):
        return -1.0, -6.0
    tail = re.split(r'[.!?:;]', tail)[-1]
    words = re.findall(r"[a-z]+(?:'[a-z]+)?", tail)[-4:]
    if not words:
        return -1.0, -6.0
    w = words[-1]
    before = words[-2] if len(words) > 1 else ''
    if w == 'as':
        return -9.5, -11.5
    change_verb = w in CHANGE and before not in (DETERMINERS | {'what', 'which'})
    if w in COPULAS or w in CONTRACTIONS or change_verb or w == 'not':
        return -6.3, -9.5
    if w in POSSESSIVES or w == 'the' or w.endswith("'s"):
        return 0.8, 0.6
    if w in {'a', 'an'}:
        return -2.2, -5.3
    if w == 'in':
        return 1.8, 0.0
    if w in {'take', 'takes', 'taking', 'took', 'taken'}:
        return 0.5, -2.0
    if w in {'best', 'most'} or w in SPATIAL or w.endswith(
            ('eastern', 'western', 'northern', 'southern')):
        return 1.2, 0.6
    if w in {'this', 'that', 'another'}:
        return -0.3, -3.0
    if w in {'any', 'some', 'each', 'every', 'which', 'many', 'no'}:
        return 0.0, -1.2
    if w in {'and', 'or'}:
        return -1.1, -8.0
    if w in {'for', 'of', 'on', 'with', 'to'}:
        return -0.7, -2.8
    if before in {'most', 'least', 'more', 'less'}:
        return 1.0, 0.3
    pos = tags(w)
    verbal = 'verb' in pos or 'adverb' in pos
    if verbal and (before in COPULAS or before in CONTRACTIONS):
        return -5.2, -8.5
    if ('adverb' in pos and len(words) > 2 and
            'adverb' in tags(before) and
            (words[-3] in COPULAS or words[-3] in CONTRACTIONS)):
        return -2.7, -7.5
    if 'adjective' in pos and (not verbal or before in DETERMINERS):
        return 0.0, -1.5
    if verbal:
        return -1.5, -5.5
    return -1.0, -6.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, before, continuation = '', '', '', 0.0
    else:
        _, tail, previous, before, continuation = carry
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    inside = bool(tail and raw and tail[-1].isalpha() and raw[0].isalpha())
    value, following = 0.0, 0.0
    if word == 'part':
        value, following = responses(tail) if not inside else (-1.0, -3.0)
        if raw.strip() != 'part':
            value = -0.6
    elif word in {'of', '-of'} and previous == 'part':
        value = continuation
    elif word == 'per' and previous == 'as' and not inside:
        value = -2.8
    elif word == 'parts':
        value = -0.25
    elif word == 'of' and previous == 'parts':
        value = -1.2
    elif word == 'of' and previous == 'as':
        value = -1.7
    elif word == 'parcel':
        value = -6.5 if previous == 'and' else -0.5
        if previous == '/or':
            value = -3.5
    elif word == 'of' and previous == 'parcel':
        value = -8.5 if before == 'and' else -1.6
    elif word == 'parte':
        value = -1.2
        if previous in {'como', 'forma'}:
            value = -10.0
        elif previous == 'come':
            value = -6.4
        elif previous == 'da':
            value = -3.2
    elif word in {'de', 'del', 'di'} and previous == 'parte':
        value = -3.0
    return (doc, (tail + raw)[-100:], word, previous, following), value

