"""layers.1.mlp.down_proj:3600 -- the "part of" membership detector.

The component is quiet almost everywhere. Its large responses are all about the word
"part" used in the sense of "belonging to a whole":

  * "is part of", "as part of", "are part of", "was part of", "become part of" ...:
    strongly negative on "part" itself (about -8) and on the "of" after it (about -10).
  * "a part of": moderately negative (about -2 on "part", -5 on "of").
  * "the upper part of", "that part of", "on the part of", "in part": about zero, since
    "part" there names a segment of something rather than membership in a whole.
  * Other uses of "part" after a word that is neither a determiner nor a preposition
    (e.g. "parte de", "part and parcel"): weakly negative (about -1).
  * "as per": mildly negative on "per" (about -2.5).

The program needs only the last three tokens, and it resets at each document boundary.
Its predictions are the activation's sign and rough size for these cases; everywhere else
it predicts 0.
"""

READS = ()

# Words right before "part" that make it membership: "is part", "as part", "forms part".
MEMBER_LEADS = {
    " is", " are", " was", " were", " be", " been", " being", " become", " became",
    " as", " As", " not", " forms", " form", " formed", " formerly", " considered",
    " legally", "'s", "’s",
}
# Words before "part" that make it a segment of something: "the part", "that part".
SEGMENT_LEADS = {
    " the", " this", " that", " his", " her", " their", " its", " our", " my", " your",
    " on", " in", " and", ",", " first", " second", " upper", " main", " early", " last",
    " other", " any", " each", " every", " at", " by", " for", " to", " of", " from",
}
ARTICLES = {" a", " an"}
PART_WORDS = {" part", "part", " Part", " parte", " parcel", " partie"}
OF_WORDS = {" of", " de", " del", " di", " della", " dei"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    cur = toks[-1]
    # the two tokens before the current one, if they are in the same document
    prev = toks[-2] if len(toks) > 1 and docs[-2] == docs[-1] else ""
    prev2 = toks[-3] if len(toks) > 2 and docs[-3] == docs[-1] else ""

    value = 0.0
    if cur in PART_WORDS:
        if prev in MEMBER_LEADS:
            value = -8.0
        elif prev in ARTICLES:
            value = -2.0
        elif prev not in SEGMENT_LEADS and prev != "":
            value = -1.0
    elif cur in OF_WORDS and prev in PART_WORDS:
        if prev2 in MEMBER_LEADS:
            value = -10.0 if cur == " of" else -4.0
        elif prev2 in ARTICLES:
            value = -5.0 if cur == " of" else -2.0
        elif prev2 in SEGMENT_LEADS:
            value = 0.0
        else:
            value = -3.0 if cur == " of" else -1.0
    elif cur == " per" and prev == " as":
        value = -2.5
    return carry, float(value)

