"""A partial detector of repetitive line formatting.

Count recent line text after normalizing digits and Chinese numeral runs.
Repeats give negative signals, mainly near line starts; numbers, their
separators and quotes after colons receive additional negative signals.
Ordinary text and newlines stay near zero. Document starts have a separate
baseline, and document changes reset the memory. Word-specific effects
and rare extreme activations are not modeled.
"""
import re
from collections import Counter

READS = ()


def normalize(text):
    text = re.sub(r'\d', '0', text)
    return re.sub('[一二三四五六七八九十百]+', '一', text)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry['document'] != document:
        carry = dict(document=document, position=0, line='',
                     line_tokens=0, lines=0, previous='', prefixes=Counter())
    c = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    line = c['line']
    key = normalize(line[-80:] + token)
    seen = c['prefixes'][key]
    punctuation = bool(word) and not any(ch.isalnum() for ch in word)

    if seen <= 1:
        if c['position'] == 0:
            if word.isalpha():
                value = -0.3905 if token[:1].isspace() else -0.4757
            else:
                value = -0.1910 if punctuation else -0.1715
        elif seen == 0:
            value = -0.0189 if len(line) <= 15 else 0.0058
        else:
            value = -0.1654 if len(line) <= 15 else -0.0104
    elif c['line_tokens'] <= 2:
        if word.isdigit():
            value = -0.8243 if not line.split() else -0.3140
        else:
            value = -0.5076 if punctuation else -0.2101
    elif c['line_tokens'] <= 7:
        value = -0.5606 if word in (':', '：') else -0.1449
    else:
        value = -0.1159 if c['lines'] == 0 else -0.0229

    # Numbered labels need not repeat the exact number to share a format.
    if c['position'] > 0:
        if not line.strip() and word.isdigit():
            value = (-0.29, -0.60, -0.90)[min(seen, 2)]
        elif punctuation and re.fullmatch(
                r'[\s\d一二三四五六七八九十百第'
                r'IVXLCDMivxlcdm()（）.．、:：-]+', line):
            value = (-0.30, -0.75, -1.10)[min(seen, 2)]
        if word in ('"', "'") and c['previous'].rstrip().endswith((':', '：')):
            value = min(value, -0.60)
        if '\n' in token:
            value = 0.02

    c['previous'] = token
    c['prefixes'][key] += 1
    # Escaped newlines, as in quoted source code, also start formatted lines.
    text = (line + token).replace('\\n', '\n').replace('\\r', '\n')
    if '\n' in text:
        c['lines'] += text.count('\n')
        c['line'] = text.rsplit('\n', 1)[-1]
        c['line_tokens'] = 0
    else:
        c['line'] = text[-160:]
        c['line_tokens'] += 1
    c['position'] += 1
    return c, value

"""Recognize compact argument, subscript, and type-parameter notation.

An opening parenthesis is stronger after a multi-letter name than after a
single mathematical letter. Subscripts and generic types behave similarly.
The first argument's comma, especially after a number, is another strong
cue; empty parentheses and quoted arguments are weaker. A number after
the first comma continues the signal. Unrecognized text and document
starts give zero. The short text suffix resets at each document boundary.
"""
import re

READS = ()
NAME = re.compile(r'[A-Za-z_][A-Za-z_0-9]*$')
NUMBER = re.compile(r'[+-]?\d+(?:\.\d+)?$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        return (doc, s[-160:]), 0.0
    tail = carry[1]
    name = NAME.search(tail)
    name = name[0] if name else ''
    letter = bool(tail) and tail[-1].isascii() and tail[-1].isalpha()
    opening = max(tail.rfind(c) for c in '([<')
    bracket = tail[opening:opening + 1] if opening >= 0 else ''
    argument = tail[opening + 1:] if opening >= 0 else ''
    closed = any(c in argument for c in ')]>{};\n')
    value = 0.0

    if s.startswith('('):
        if s.startswith('()'):
            value = 0.14
        elif s[1:2] in ('"', "'"):
            value = 0.26
        elif any(c.isalpha() for c in s):
            value = 0.86 if len(name) > 1 else (0.48 if letter else 0.15)
        else:
            value = 0.76 if letter else 0.14
            if letter and len(name) == 1:
                value = 0.49
    elif s.startswith('['):
        value = 0.09
        if letter:
            if s[1:2] in ('"', "'"):
                value = 0.22
            elif name[:1].isupper():
                value = 0.52
            else:
                value = 0.99 if any(c.isalpha() for c in s) else 0.70
    elif s.startswith('<') or s.startswith('::<'):
        if not any(c in s for c in ')]>'):
            if name[:1].isupper():
                value = 0.75 if bracket == '<' else 1.32
            elif letter and not s.startswith(('</', '<|')):
                value = 0.19
    elif s.lstrip("\"'\\(){}").startswith(','):
        if NUMBER.fullmatch(argument.strip()):
            value = 0.10
            if len(s) == 1:
                value = 0.93 if bracket == '(' else 0.25
        elif (argument and not closed
              and not any(c.isspace() for c in argument)):
            if not any(c in s for c in ')]>'):
                value = 0.57 if bracket == '(' else 0.24
                if ',' in argument:
                    value = 0.20
    elif s.strip().isdigit() and bracket == '(' and not closed:
        if re.fullmatch(r'[^,\s]{1,30},\s*', argument):
            value = 0.35
    return (doc, (tail + s)[-160:]), value

