Look for the syllable in a token, or completed after a preceding b.  Case,
word boundaries, accents, and German/Hungarian/Vietnamese-looking context
change its strength.  Mandarin readings provide a weak extension to Han characters.
Half compounds have separate strengths; a little response can persist into
one following piece.  Unmatched tokens get zero, not token-specific offsets.
"""
import codecs
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from pypinyin import lazy_pinyin
from wordfreq import zipf_frequency
import regex

READS = ()
GERMAN = {'der', 'die', 'das', 'und', 'nicht', 'von', 'mit', 'zu', 'den'}
HUNGARIAN = {'az', 'egy', 'hogy', 'és', 'nem', 'már', 'volt', 'csak'}


@lru_cache(maxsize=20000)
def spelling(s):
    return anyascii(s).lower()


@lru_cache(maxsize=20000)
def readings(s):
    return tuple(lazy_pinyin(s))


def response(s, previous, recent):
    word = s.strip()
    if not word:
        return 0.0
    # Half: isolated character, numerical fraction, latter/lower half, majority.
    if word == '半':
        if previous.endswith('一'):
            return 2.4
        if previous.endswith(('后', '後')):
            return 10.5
        if previous.endswith('大'):
            return 7.1
        return 11.3 if s[0].isspace() or previous.endswith(' ') else 8.6
    if '半' in word:
        return 5.4 if word == '下半' else 2.0
    w = spelling(word)
    boundary = s[0].isspace()
    if regex.search(r'\p{Script=Han}', word):
        if (previous.endswith('半') and not recent.endswith('一半')
                and not word.startswith('的')):
            return 1.0
        sounds = readings(word)
        if 'ban' in sounds:
            return 0.6 if len(sounds) == 1 else 0.2
        return 0.2 if set(sounds).intersection(('pan', 'fan')) else 0.0
    if regex.search(r'\p{Script=Hangul}', word):
        if w == 'ban':
            return 8.0
        if w == 'pan':
            return 1.5
        return 1.0 if previous.strip() == '반' and not boundary else 0.0
    if w == 'ban' and regex.search(r'[\p{Hiragana}\p{Katakana}]', word):
        return 4.1

    if (w in ('ban', 'ben', 'bans')
            and not regex.match(r'[\p{Latin}\p{Cyrillic}]', word)):
        return 1.5
    marks = unicodedata.normalize('NFD', word)
    if w in ('ban', 'bans'):
        if '\u0323' in marks:  # Vietnamese dot-below forms are not this response.
            return 0.0
        if set(marks).intersection(('\u0301', '\u0309')):
            return 2.9
        if any(c in recent for c in 'đĐơƠưƯ'):
            return 7.5
        if boundary and regex.search(r'\p{Script=Cyrillic}', word):
            return 1.0
        if word[0].isupper():
            return 3.0
        return 3.1 if boundary else 6.3
    words = set(re.findall(r'[^\W\d_]+', recent.lower())) if 'en' in w else set()
    german = len(words & GERMAN) >= 2
    if w == 'ben':
        if word[0].isupper():
            return 2.8 if '\u0302' in marks else 0.5
        if boundary:
            return 1.2
        if german:
            return 0.2
        if set(recent).intersection('őűŐŰ') or len(words & HUNGARIAN) >= 2:
