        return 3.3 if word[0].isupper() else 1.5
    if w == 'bn':
        return 0.6
    if not boundary:
        before = spelling(previous)
        if before.endswith('b'):
            if not regex.match(r'[\p{Latin}\p{Cyrillic}]', word):
                return 0.0
            if regex.match(r'\p{Cyrillic}', word) and len(previous.strip()) > 1:
