"""Approximate negative responses to short an-/am-like spelling pieces.

The large negative response is most common in German/Danish/Dutch and
Vietnamese, not the English article 'an'. Recent word frequencies estimate
that context. Related spellings in Chinese, Korean, Japanese, Cyrillic,
Greek and Persian get simple fixed responses. Token boundaries and case
adjust the strength; most other tokens get zero. This approximates the large
negative responses, not the component's smaller background fluctuations.
"""
import codecs
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


def clip(x):
    return max(0.0, min(1.0, x))


@lru_cache(maxsize=32768)
def word_evidence(word):
    if len(word) < 2:
        return 0.0, 0.0
    en = zipf_frequency(word, 'en')
    strong = max(zipf_frequency(word, lang)
                 for lang in ('de', 'da', 'nl', 'vi'))
    other = max(zipf_frequency(word, lang)
                for lang in ('pt', 'es', 'fr', 'it', 'tr', 'id', 'ro'))
    limit = lambda x: max(-2.0, min(2.0, x))
    return limit(strong - max(en, other)), limit(en - max(strong, other))


def context(text):
    words = re.findall(r"[^\W\d_]+", text)[-24:]
    scores = [word_evidence(w.lower()) for w in words]
    weights = [.88 ** i for i in range(len(scores) - 1, -1, -1)]
    evidence = sum(w * (max(g, 0) + .3 * min(g, 0))
                   for (g, e), w in zip(scores, weights))
    english = sum(w * e for (g, e), w in zip(scores, weights))
    foreign = clip(-english / 3.6)
    return min(clip(evidence / 3), foreign), foreign


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, pending = '', b''
    else:
        _, text, pending = carry
    data = pending + prefix.token_bytes[-1]
    token, used = codecs.utf_8_decode(data, 'replace', False)
    pending = data[used:]
    if token in ('<|endoftext|>', '<|im_start|>', '<|im_end|>'):
        return (doc, '', pending), 0.0
    s = token.strip()
    low = s.lower()
    value = 0.0
    if s == '安':
        value = -4.2
    elif s.endswith('安') or s.endswith('安市'):
        value = -2.6
    elif s == '安卓':
        value = -1.2
    elif s == '안':
        value = -4.3 if token[:1].isspace() else -2.8
    elif s in ('アン', 'あん'):
        value = -2.0
    elif low == 'ан':
        value = -1.2
    elif s == 'آ':
        value = -2.3
    elif s == 'ن' and text.endswith('آ'):
        value = -6.4
    elif s in ('ン', 'ん') and text.endswith(('ア', 'あ')):
