"""Recognize stock code and web-interface fragments, leaving other tokens at zero.

Strong negative responses occur in option registration (add_argument and
click.option), Swing layout builders, and certain forum headings/counters.
Weaker rules recognize SQL CREATE TABLE, viewport metadata, request methods,
and comment authors. Document-opening navigation words have their own offsets.
Initial middot-only padding runs also receive a negative response.
This sparse approximation omits small, ordinary lexical fluctuations.
"""
import re

READS = ()

# Imperative navigation labels / video-description openings.
OPENING_LABELS = {
    "Show": -2.42,
    "Showing": -5.39,
    "Search": -3.20,
    "Tap": -3.70,
    "View": -1.66,
    "Views": -2.01,
    "Skip": -2.51,
    "Filter": -2.30,
    "Login": -2.45,
    "切换": -4.79,  # Switch (Chinese interface label).
    "More": 4.38,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, position, criteria_count = b"", 0, 0
        dots_only, layout_seen = True, False
    else:
        _, history, position, criteria_count, dots_only, layout_seen = carry
    token = prefix.token_strings[-1]
    text = history.decode("utf-8", errors="replace")
    value = 0.0
    layout_seen = layout_seen or "GroupLayout" in text

    # Command-line option definitions, with procedural versus object receivers.
    if token == "_argument" and text.endswith(".add"):
        value = -15.2 if re.search(r"\bparser\.add$", text) else -10.5
        if text.endswith("self.add"):
            value = -8.7
    elif token == ".option" and text.endswith("click"):
        value = -6.7

    # Java Swing's nested, generated layout-building idiom.
    elif token == "addGroup" and layout_seen and text.endswith("."):
        value = -10.5
    elif token == ".Alignment" and text.endswith("GroupLayout"):
        value = -2.2
    elif token == "addGap" and layout_seen and text.endswith("."):
        value = -2.2
    elif token == "_VALUE" and text.endswith("Short.MAX"):
        value = -1.5

    # Web/forum boilerplate. Spaced bullet labels differ from bare headings.
    elif token == "Topics":
        value = -22.0 if re.search(r"Similar\s+$", text) else 0.55
    elif token == " Views" and text.rstrip().endswith("•"):
        value = -7.6 if "Replies:" in text else -1.0
    elif token == "Views" and "Replies" in text:
        value = 0.5
    elif token == "viewport" and re.search(r'meta\s+name=[\'\"]$', text):
        value = -6.0
    elif token == "username" and text.endswith("<issue_comment>"):
        value = -2.2
    elif token == "/url" and text.endswith("google.com"):
        value = -1.8
    elif token == "起" and text.endswith("收"):
        value = -2.3  # The Chinese 'collapse/fold up' phrase 收起.

    # Other recognizable programming phrases.
    elif token == " TABLE" and text.endswith("CREATE"):
        value = -1.65
    elif token == ".Command" and text.endswith("cobra"):
        value = -1.8
    elif token == " Criteria" and text.endswith("public"):
        value = -min(1.4, 0.1 * criteria_count)
        criteria_count += 1
    elif token == "GET" and re.search(r'\.open\([\'\"]$', text):
        value = -1.8
    elif token == " help" and text.endswith("Get more"):
        value = -2.3
    elif token == "··":
        value = -1.1 if dots_only else -0.35

    if position == 0:
        value = OPENING_LABELS.get(token, value)
        if token == "def":
            value = -3.26
        elif token.strip() == "import":
            value = -3.2 if token.startswith("\t") else -1.33
        elif token == "using":
            value = 1.55
        elif token == "test":
            value = -2.7

    carry = (doc, (history + prefix.token_bytes[-1])[-256:],
             position + 1, criteria_count, dots_only and token == "··",
             layout_seen)
    return carry, value

"""A partial lexical and orthographic description.

Positive spikes mark selected expressions, chiefly Chinese/Japanese, of completeness,
restriction, breadth, sufficiency and sameness. Recent bytes identify split
compounds and adjective endings. There are also byte-fragment preferences
for the beginnings of 紛 (numerous), 緊 (tight) and 纺 (spin).
Two split Korean/Vietnamese expressions and a few character/punctuation
preferences are retained explicitly. State resets between documents.
The many small, word-specific responses are not reconstructed.
"""
import codecs
from functools import lru_cache
from opencc import OpenCC

READS = ()
_converter = OpenCC('t2s')


@lru_cache(maxsize=12000)
def simplify(word):
    return word if word.isascii() else _converter.convert(word)


# Shared UTF-8 beginnings of the strongly responding characters below.
# These are character spellings, not tokenizer IDs.
NUMEROUS_PREFIX = '紛'.encode('utf-8')[:2]
CHARACTER_PREFIXES = {ch.encode('utf-8')[:2] for ch in '紛緊纺'}


def lexical_value(word):
    if word == '完全':
        return 4.1
    if word in {'仅', '仅仅'}:
        return 3.3
    if word == '不仅仅':
        return 2.4
    if word in {'不仅是', '不只是'}:
        return 1.8
    if word in {'不仅', '的主要'}:
        return 0.7
    if word in {'主要', '十分', '只是', '常常'}:
        return 0.55
    if word in {'专门', '主要是', '同样', '同样的', '纯粹', '全く'}:
        return 1.6
    if word in {'明显', '明显的', '显然', '单独', '单纯的'}:
        return 1.1
    if word in {'充分', '紧密'}:
        return 2.1
    if word in {'广泛', '广泛的'}:
        return 3.1
    if word == '泛':
        return 2.5
    if word == '普遍':
        return 0.85
    if word == '纷':
        return 2.3
    if word == '纷纷':
        return 1.1
    if word == '繁':
        return 0.4
    if word == '全':
        return -0.4
    # Additional stable single-character preferences: spinning and dissolving.
    if word == '纺':
        return 3.4
    if word == '溶':
        return 1.3
    if word in {'免费', '無料'}:
        return 0.3
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        decoder = codecs.getincrementaldecoder('utf-8')(errors='replace')
        previous = ''
    else:
        decoder, previous = carry[1:]
    fragmented = bool(decoder.getstate()[0])
    raw = decoder.decode(prefix.token_bytes[-1], final=False)
    word = simplify(raw)
    value = lexical_value(word) if not first else -0.002

    if not first:
        # Parts of recognizable compounds need their preceding stem.
        if word == '纯' and previous.endswith(('单', '単')):
            value = 4.2
        elif word == '순' and previous.strip().endswith('단'):
            value = 4.4
        elif word == '门' and previous.endswith(('专', '専')):
            value = 1.7 if previous.endswith('専') else 3.7
        elif word == '样' and previous.endswith('同'):
            value = 5.0
        elif word == '密' and previous.endswith('紧'):
            value = 3.8
        elif word == '繁' and previous.endswith(('纷', '频')):
            value = 3.0
        elif word == '凭' and previous.endswith(('仅', '光')):
            value = 4.8
        elif word == '全' and previous.endswith('完全'):
            value = 7.0
        elif word == '完全' and previous.endswith('完'):
            value = 7.0
        elif word == ' toàn' and previous.rstrip().endswith('hoàn'):
            value = 4.5
        elif word == '分' and previous.endswith(('万', '过', '多')):
            value = 1.2

        # Japanese manner/adjective particles, stronger after scope words.
        elif word == 'に':
            value = 0.12
            if previous.endswith('完全'):
                value = 2.7
            elif previous.endswith(('纯', '単')):
                value = 2.0
            elif previous.endswith(('更', '既', '仮', '同様', 'とも', '実')):
                value = 1.0
        elif word == 'な':
            value = 0.28
            if previous.endswith('多様'):
                value = 2.5
            elif previous.endswith(('同様', '密', '绮丽', '主要')):
                value = 1.5
        elif word == 'ん':
            value = -0.24
        elif word == 'が':
            value = -0.11
        elif word == ' often':
            value = -0.05
            if previous.rstrip().endswith((' more', ' most', ' so', ' too',
                                            ' less', ' quite')):
                value = -0.8
        elif word == '常':
            value = -0.1
            if previous.endswith(('最', '时', '惯')):
                value = -0.9
        elif word == '··':
            value = -1.25

    # A fragmented character can have a response before its final byte arrives.
    pending = decoder.getstate()[0]
    if not first and pending in CHARACTER_PREFIXES:
        if fragmented:
            value = 3.0
        elif pending == NUMEROUS_PREFIX:
            value = 1.1
    elif not first and fragmented and raw == '紛':
        value = 5.3

    return (doc, decoder, (previous + word)[-12:]), value

