"""layers.1.mlp.down_proj:3607 -- a "completely / only / widely / especially" adverb detector.

In plain terms: this component's output is almost always near zero. It becomes large on a
small set of Chinese and Japanese adverbs that restrict, intensify or spread the predicate
that follows them:
  - "completely" 完全 (about +4), "only" 仅 / 僅 / 仅仅 (about +3), "widely" 广泛 (about +3),
    "fully" 充分, "closely" 紧密, "purely" 純 (about +1 to +2);
  - milder ones such as "specially" 专门, "likewise" 同样, "obviously" 明显 / 显然,
    "mainly" 主要是, "one after another" 纷纷 (about +1 to +2); "not only" 不仅 and similar
  weaker words (十分, 只是, 主要, 常常, 类似) sit between +0.3 and +0.6;
  - a few very common function words (就, 这, 要, 通过, 从) sit slightly below zero.
Adverbs split across two tokens count too: the second token of 广|泛 or 紧|密 gets the word's
value. A token that begins with one of these words (广泛的, 完全可以) gets 80% of it.

The program reads the current token and the one before it (the carry), reset at each
document boundary. Its values are the average activations measured on the training rows, so
it is a readable word list, not a per-token table of arbitrary ids. What it leaves out: a long
tail of tokens with small consistent offsets (a full token table reaches about 0.25 variance
explained on held-out rows, this list about 0.10), and the context that flips the sign on some
words.
"""

# Adverbs of completeness, exclusivity, extent and manner (simplified, traditional, Japanese),
# with the component's typical activation on them.
STRONG = {
    "完全": 4.2, "仅": 2.8, "僅": 3.2, "仅仅": 3.8, "僅僅": 3.8, "仅仅是": 3.8,
    "广泛": 2.9, "廣泛": 2.9, "泛": 2.2, "充分": 2.0, "紧密": 2.1, "緊密": 2.1,
    "純": 1.1, "全然": 2.0, "全く": 1.7, "单纯": 2.4,
}
MEDIUM = {
    "专门": 1.6, "專門": 1.6, "同样": 1.4, "同樣": 1.5, "明显": 1.4, "明顯": 1.4,
    "显然": 1.05, "顯然": 1.05, "主要是": 1.3, "纷纷": 1.2, "紛紛": 1.2, "普遍": 0.9,
    "纯粹": 1.5, "純粹": 1.5, "单独": 1.0, "單獨": 1.0, "纷": 2.3, "紛": 2.3,
    "不仅是": 2.1, "不僅是": 2.1, "不仅仅": 2.3, "不僅僅": 2.3,
}
WEAK = {
    "十分": 0.6, "不仅": 0.6, "不僅": 0.6, "只是": 0.4, "主要": 0.5, "常常": 0.6,
    "往往": 0.5, "类似": 0.6, "類似": 0.6, "相似": 0.5, "复杂": 0.5, "严重": 0.4,
    "绝对": 0.4, "根本": 0.3, "几乎": 0.3, "并不": 0.35, "全新": 0.6, "独": 0.4,
    "獨": 0.4, "然": 0.3, "严格": 0.3,
}
# Very common function words that sit slightly below zero.
FUNCTION = {"就": -0.25, "这": -0.24, "要": -0.18, "通过": -0.22, "从": -0.17}

WORDS = {**FUNCTION, **WEAK, **MEDIUM, **STRONG}
READS = ()


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = carry if carry is not None else ""
    if len(prefix.document_ids) > 1 and prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""
    if prev and prev + cur in WORDS:
        value = WORDS[prev + cur]
    elif cur in WORDS:
        value = WORDS[cur]
    else:
        value = 0.0
        for word, val in {**STRONG, **MEDIUM}.items():
            if len(word) > 1 and cur.startswith(word):
                value = 0.8 * val
    return cur, float(value)

"""Fires on years and on the first token of a text.

* Code: the keyword " new" right after "=", "throw" or "return" (creating an object).
* Years: the fourth digit of a number that starts 19 or 20 (a 1900s/2000s year),
  e.g. the "8" of "2008". Strongest for 19xx and 20xx; weaker for 18xx.
* First token of a document or of a row, where the model has no context yet:
  strength depends on the kind of word it is (common function words high, content
  words after a space moderate, digits and identifiers low).
"""
READS = ()

FUNCTION_WORDS = set(
    "a an the of to and or but is was are were be been it its in on at by for with as "
    "from that this these those he she they we you i my your his her their our not no "
    "so if can will would should could do does did have has had".split()
)

def _is_digit(s):
    return len(s) == 1 and s.isdigit()

def _start_value(s):
    word = s.strip().lower()
    if word == "":
        return 0.5
    if word.isdigit():
        return -0.4
    if not word.isascii():
        return 0.6
    if word.isalpha():
        if word in FUNCTION_WORDS:
            return 2.0 if s[0] == " " else 1.0
        return 1.2 if s[0] == " " else -0.2
    return 0.5

def step(carry, prefix, upstream):
    s = prefix.token_strings
    t = prefix.position
    cur = s[-1]
    if t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, _start_value(cur)
    if cur == " new" and s[-2] in (" =", " throw", " return"):
        return carry, 0.9
    if t >= 3 and all(_is_digit(x) for x in s[-4:]) and (t < 4 or not _is_digit(s[-5])):
        pre = s[-4] + s[-3]
        if pre in ("19", "20"):
            return carry, 0.95
        if pre == "18":
            return carry, 0.5
    return carry, 0.0

programs.sol:
"""A sparse lexical approximation, not a general topic detector.

Five is strongest in technical suffixes; decimal .5 is negative. Other
positive cases include 30/31 (especially dates), short/kurz/kort, Chinese
numeral phrases, selected ro/luo syllables, RLE '2o', Apollo and 二极管.
Document-initial markup and line breaks have separate formatting responses.
Everything else is near zero. State retains 80 characters and the last token,
resetting at document boundaries.
"""
import re
from pypinyin import lazy_pinyin

READS = ()
MONTH = re.compile(
    r'(?:January|February|March|April|May|June|July|August|September|'
    r'October|November|December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Oct|'
    r'Nov|Dec)\.?[, ]+3$', re.I)
TECH_FIVE = re.compile(
    r'(?:md|hdf|html|sha|perl/?|java|mozilla/|playstation\s*|'
    r'ps|route|ue|il-|gad6|json|qt|yolov|s&p\s*)$', re.I)
LUO_PREFIXES = set('波杰傑马馬亚亞潘伊叶葉色洛菠诺諾')
COUNT_CLASSIFIERS = set('个個种種款座篇项項件道关關炮次些')
SHORT = ('short', 'kurz', 'kort')
FIVE_WORDS = ('five', 'fifth', 'fifths', 'fifteen', 'fifteenth', 'fifty', 'fiftieth')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    tail = '' if start else carry[1]
    previous = '' if start else carry[2]
    token = prefix.token_strings[-1]
    text = tail + token
    value = -0.002

    if token == '5':
        value = 0.16
        if previous.isdigit():
            value = 0.06
        elif previous.endswith('.'):
            value = -0.22
        elif previous and previous[-1].isalpha():
            value = 0.48
        elif previous.endswith(('/', '_')):
            value = 0.28
        if TECH_FIVE.search(tail):
            value = 1.45
        if re.search(r'(?:md|hdf|html|json)$', tail, re.I):
            value = 2.0
    elif token in ('0', '1') and previous == '3':
        value = 0.40 if token == '0' else 0.16
        if MONTH.search(tail) or re.search(r'月3$', tail):
            value = 0.95
        elif token == '0' and re.search(r'[:：]3$', tail):
            value = 0.72
    elif token == '0' and tail == '2':
        value = 0.99

    # Match a word at the position where its identifying part first arrives.
    old_word = re.search(r'[A-Za-z]+$', tail)
    new_word = re.search(r'[A-Za-z]+$', text)
    word = new_word[0].lower() if new_word else ''
    old = old_word[0].lower() if old_word else ''
    split = bool(old and token[:1].isalpha()
                 and not tail.endswith(('\\n', '\\t', '\\r')))
    if word in FIVE_WORDS and word != old:
        value = 1.20 if split else 0.30
        if word == 'five' and not split:
            value = 0.50 if new_word[0][0].isupper() else 0.17
    elif word == 'friday' and word != old:
        value = 1.35 if tail.rstrip().endswith('Black') else 0.32
    elif word == 'shortly' and word != old:
        value = 0.65 if split else 0.55
    elif word.startswith(SHORT) and not old.startswith(SHORT):
        if word.startswith('kurz'):
            value = 1.0
        elif word.startswith('kort'):
            value = 0.65
        else:
            value = 0.85 if split else 0.13

    if token in ('五', '伍', '十五'):
        value = 0.30 if token != '十五' else 0.7
        if token == '五' and tail.endswith('星期'):
            value = 1.0
    elif token == '九' and tail.endswith('一'):
        value = 3.4 if previous == '在一' else (0.8 if tail.endswith('九一') else 2.6)
    elif token.startswith('一') and tail and tail[-1] in '这這那哪':
        value = 1.6 if len(token) > 1 and token[1] in COUNT_CLASSIFIERS else 0.3
    elif token[:2] in ('这一', '這一', '那一', '哪一') and len(token) > 2:
        value = 1.0
    elif tail.endswith(('这一', '這一')) and len(token) == 1:
        value = 0.8
    elif token in ('一页', '一頁') and tail and tail[-1] in '上下':
        value = 0.55

    # The same ro-like syllable occurs in several writing systems.
    if token == 'ロ':
        if previous in ('ア', 'サ', 'ヒ'):
            value = 1.5
        elif previous in ('フォ', 'セ'):
            value = 1.2
        elif previous in ('コ', 'タ'):
            value = 0.6
    elif token == '로' and previous.strip() == '가':
        value = 1.23
    elif token == 'رو' and previous.strip() in ('ی', 'پ'):
        value = 2.4
    elif len(token) == 1 and previous in LUO_PREFIXES and lazy_pinyin(token) == ['luo']:
        value = 1.8
    elif token == 'o' and previous == '2' and re.search(r'[bo]\d*2$', tail):
        value = 0.8  # Run-length encoded live cells in cellular automata.

    # Two further lexical peaks: Apollo, and the start of 'diode' (二极管).
    if token.strip() == 'Apollo':
        value = 1.6
    elif previous == '二' and token == '极':
        value = 2.1

    if start:
        if token == '<':
            value = 1.27
        elif token.isspace() and '\n' in token:
            multiple = token.count('\n') > 1
            if '\r' in token:
                value = 1.62 if multiple else 1.44
            elif token.startswith(' '):
                value = 0.62 if multiple else 0.90
            else:
                value = 0.48 if multiple else 0.19

    return (doc, text[-80:], token), float(value)

"""A sparse spelling-based approximation, rather than a semantic classifier.

Short bil/bill/Bild fragments and split b + il spellings are negative;
recent Turkish-specific letters strengthen some responses. Weaker rules cover
b followed by certain vowel/liquid fragments. Complete
words such as ability and billion are excluded. Russian образ, the Han
character 拜 have separate negative responses.
A likely b-prefixed byte/character literal is positive. Other tokens get 0.
The state keeps the last token and 128 text characters, reset by document.
Coefficients are fixed group amplitudes, not exact activation predictions.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=8192)
def romanize(text):
    return anyascii(text).lower()


def response(token, previous, tail):
    s = token.strip()
    low = s.lower()
    roman = romanize(s)
    prev = romanize(previous)

    if low == 'образ':
        return -4.9  # image/form root
    if s == '拜':
        return -3.6  # bow character
    if token == "'s":
        return 0.0  # other
    if token.startswith("'") and re.search(r"(?:^|[\s(=,:@|+\-])b$", tail):
        # Do not mistake the end of a quoted expression for a byte prefix.
        if tail.rsplit('\n', 1)[-1].count("'") % 2 == 0:
            return 3.5  # byte literal
    turkish = bool(re.search('[ıİğĞşŞ]', tail[-40:]))
    if re.fullmatch(r'bil(?:l(?:s|ed|ing)?|d(?:er|ung)?|e)?', low):
        if turkish and low in ('bil', 'bill', 'bile'):
            return -4.6  # Turkish bil fragment
        if (not token[0].isspace() and s.islower()
                and low in ('bil', 'bild', 'bill')):
            return -4.8  # embedded bil fragment
        if low == 'bilder' and token[0].isspace():
            return 0.0  # other
        if low == 'billing' and s.islower():
            return -1.0  # billing word
        if low in ('bil', 'bild'):
            return -3.3  # bare bil/bild
        if s.isupper():
            return -4.8  # capitalized bill
        if low == 'bills':
            return -3.2  # plural bills
        return -2.1  # bill family
    if re.fullmatch(r'[aei]bil(?:e)?', low):
        if turkish:
            return -4.6  # Turkish bil fragment
        return -1.3  # vowel + bil fragment

    # A continuation inside the same word: no space at this boundary.
    if token and not token[0].isspace():
        if prev.endswith('b'):
            if roman == 'ild':
                return -8.3  # b + ild
            if roman.startswith(('il', 'yl')) and len(roman) <= 5:
                if roman in ('ility', 'ilit') or roman.endswith(('sya', 'sia')):
                    return 0.0  # other
                if turkish and roman in ('il', 'ilm', 'iler'):
                    return -4.6  # Turkish bil fragment
                if len(roman) > 2 and roman[2] in 'aeiouy':
                    return -2.3  # b + il-vowel
                return -3.6  # b + il
            if s == 'ao':
                return -4.0  # b + ao
            if roman.startswith(('ell', 'ay', 'au', 'ai')):
                return -0.4  # b + other vowel
            if roman.startswith(('li', 'ly')):
                return -0.3  # b + l
        if prev.endswith('be') and roman == 'eld':
            return -3.8  # Dutch beeld split
    return 0.0  # other


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, tail)
    return (doc, token, (tail + token)[-128:]), value

"""A lexical conditional/alternative signal, with a few context adjustments.

'If' introduces a condition, except after checking/knowing verbs, where it
usually means 'whether'. Boolean operators are strongest in code conditions.
Translations are recognized too; recent word frequencies disambiguate short
Romance words. URL separators respond positively, and a document-opening
'Title:' colon has a separate large response. State resets between documents.
This is a surface-text approximation, not a parser or a truth evaluator.
"""
import re
import wordnet
from wordfreq import zipf_frequency

READS = ()

# Translations of 'if' and 'or'; ambiguous short words have weaker responses.
TRANSLATIONS = {
    'если': 1.1, 'oder': 0.68, 'или': 0.52, 'ou': 0.9,
    'eller': 0.61, 'vagy': 0.82, 'atau': 0.42, 'أو': 0.42,
    'nếu': 0.75, 'si': 0.52, 'se': 0.09, 'o': 0.05,
}
CHECKING = {'check', 'determine', 'test', 'verify', 'specify'}
KNOWING = {'know', 'see', 'ask', 'wonder', 'tell', 'decide'}


def language(tail):
    """Choose the language whose ordinary words best fit the recent text."""
    words = re.findall(r"[^\W\d_]+", tail.lower())[-24:]
    if not words:
        return 'en'
    languages = ('en', 'it', 'pt', 'es', 'fr', 'cs')
    return max(languages, key=lambda lang: sum(
        max(0.0, zipf_frequency(w, lang) - 3.0) for w in words))


def category(text, tail):
    word = text.strip()
    low = word.lower()
    boundary = text[:1].isspace() or not tail or not tail[-1].isalnum()
    if word == ':' and tail == 'Title':
        return 'title_colon'
    if word == '://':
        return 'URL'
    if word in {'&&', '||'} or low in {'and', 'or'}:
        condition = re.search(r'\b(?:if|elif|while)\b([^;{}:]*)$', tail)
        code_line = re.search(
            r'(?:^|\n|\\n)[ \t+\d]*(?:else\s+)?'
            r'(?:if|elif|while)\b[^;{}\n]*$', tail)
        syntax = condition and re.search(r'[().=<>!\[\]]', condition[1])
        if word in {'AND', 'OR'} and re.search(
                r'\b(?:WHERE|ON)\b[^;]*[=<>]', tail):
            return 'SQL_boolean'
        if word in {'&&', '||'} and condition:
            return 'condition_operator'
        if code_line and syntax and boundary:
            return 'condition_word'
        if word == '&&':
            return 'shell_and'
        if word == '||':
            return 'other_bars'
        if low == 'and':
            return 'and'
        if low == 'or':
            if not boundary:
                return 'or_suffix'
            if not text[:1].isspace() and word == 'or':
                return 'or_separate'
            return 'or'
    if word == '/or':
        return 'and_or'
    if low in {'if', 'elif', 'elseif'}:
        if not boundary:
            return 'if_suffix'
        if low != 'if':
            return 'else_if'
        previous = re.search(r'([A-Za-z]+)\s*$', tail)
        prev = previous[1].lower() if previous else ''
        bases = set(wordnet.base_forms(prev)) | {prev}
        if bases & CHECKING:
            return 'checking_if'
        if bases & KNOWING or prev == 'sure':
            return 'whether_if'
        if prev == 'as':
            return 'as_if'
        if prev in {'only', 'what'}:
            return 'qualified_if'
        if word == 'IF':
            return 'uppercase_if'
        if prev == 'else':
            return 'else_if'
        if re.search(r'(?:^|\n|\\n)[ \t]*$', tail):
            return 'indented_if'
        return 'if'
    if boundary and low in {'se', 'si', 'o'}:
        lang = language(tail)
        if low == 'se' and lang in {'it', 'pt'}:
            return 'Romance_se'
        if low == 'si' and lang in {'es', 'fr'}:
            return 'Romance_si'
        if low == 'o' and lang in {'it', 'es'}:
            return 'Romance_o'
        return 'other'
    if boundary and low in TRANSLATIONS:
        return low
    completed = re.search(r'([^\W\d_]+)$', tail + text)
    if completed and len(completed[1]) > len(word):
        whole = completed[1].lower()
        if whole in TRANSLATIONS or whole in {'jika', 'nebo', 'abo', 'або'}:
            return 'completed_alternative'
    if word.startswith(('如果', '假如', '假设')):
        return 'Chinese_if'
    if word in {'或', '或者'}:
        return 'Chinese_or'
    return 'other'


VALUES = {
    'title_colon': 10.3, 'Romance_se': 1.2, 'Romance_si': 1.1,
    'Romance_o': 1.0, 'completed_alternative': 1.2, 'SQL_boolean': 1.1,
    'URL': 1.0, 'condition_operator': 1.75, 'condition_word': 1.5,
    'shell_and': 0.43, 'and': -0.012, 'uppercase_if': 0.2,
    'other_bars': 0.0, 'or': 0.33, 'or_suffix': -0.12,
    'or_separate': 0.6, 'and_or': 0.52, 'if_suffix': -0.2,
    'else_if': 1.0, 'checking_if': -0.3, 'whether_if': 0.0,
    'as_if': -0.18, 'qualified_if': 0.18, 'indented_if': 0.75,
    'if': 0.68, 'Chinese_if': 0.45, 'Chinese_or': 0.18,
    'other': 0.0,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    kind = category(text, tail)
    value = TRANSLATIONS.get(kind, VALUES.get(kind, 0.0))
    recent = (tail + text).replace(r'\n', '\n').replace(r'\t', '\t')
    return (doc, recent[-240:]), value

programs.haiku:
"""Branch words: the tokens that open a condition or a choice, in prose or in code.

The component fires on
- "if" as a standalone word. It is strongest when the word opens a clause or a
  statement (after punctuation, a line start, or "else": "If it rains", "else if (");
  weaker when it completes a verb ("check if", "as if", "see if");
- "elif", and "or" / "ou" / "oder" / "или" as a standalone word (a choice); the
  conditional words "se" / "si" / "если" / "如果" in Spanish, Italian, Russian, Chinese;
- the logical operators "||" and "&&", strongest on an `if (...)` line where they join
  the conditions; not inside markdown tables;
- "AND" / "OR" in SQL-style logic, and the "://" of a URL (a weaker, separate case);
- the colon of a document's "Title:" header, right after the end-of-document marker
  (a rare but very large spike).
It stays near zero on "and", "not", "else", "of", and on these letters inside a longer
word ("LIBOR", "ATTORNEY", "eirigsten").

Value: a rough strength for each token; 0 everywhere else."""

READS = ()

# Words that start a condition or a choice in other languages, matched as whole tokens.
FOREIGN = {"если": 1.0, "или": 0.5, "如果": 0.5, "wenn": 0.5}
OR_WORDS = {"or": 0.35, "ou": 0.6, "oder": 0.5, "o": 0.1}
WEAK_WORDS = {"se": 0.2, "si": 0.3}
CAPS_LOGIC = {"AND": 0.4, "OR": 0.6}
OPERATORS = {"||": 1.0, "&&": 0.5}
IN_IF_LINE = {"||": 2.0, "&&": 1.4}
TITLE_SPIKE = 10.28


def current_line(prefix):
    """The text of the current line, up to the token before this one."""
    words = []
    for piece in reversed(prefix.token_strings[:-1]):
        if "\n" in piece:
            words.append(piece.split("\n")[-1])
            break
        words.append(piece)
    return "".join(reversed(words))


def is_word_start(prefix, raw):
    """A token starts a word: it has a leading space or newline, or follows punctuation."""
    if raw[:1] in " \t\n" or len(prefix.token_strings) == 1:
        return True
    before = prefix.token_strings[-2]
    return not (before[-1:].isalnum() or before[-1:] == "_")


def if_strength(prefix):
    """How strongly a standalone `if` opens a condition, from the token before it."""
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if before == "else" or not before or not before[-1].isalnum():
        return 0.8
    return 0.3


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip()
    lower = word.lower()
    if word == ":" and len(prefix.token_strings) > 2:
        if prefix.token_strings[-2] == "Title" and prefix.token_strings[-3] == "<|endoftext|>":
            return None, TITLE_SPIKE
    if word == "://":
        return None, 1.0
    if word in OPERATORS:
        if current_line(prefix).lstrip().startswith("|"):
            return None, 0.0  # a markdown table row, not code
        return None, IN_IF_LINE[word] if "if" in current_line(prefix).lower().split() or "if (" in current_line(prefix) else OPERATORS[word]
    if word in CAPS_LOGIC and raw[:1] == " ":
        return None, CAPS_LOGIC[word]
    if lower in FOREIGN:
        return None, FOREIGN[lower]
    if not is_word_start(prefix, raw):
        return None, 0.0  # a piece of a longer word
    if lower == "if":
        return None, if_strength(prefix)
    if lower == "elif":
        return None, 0.9
    if lower in OR_WORDS:
        return None, OR_WORDS[lower]
    if lower in WEAK_WORDS:
        return None, WEAK_WORDS[lower]
    return None, 0.0

programs.sol:
"""A lexical approximation, strongest on Chinese execution and completion.

Recent computing keywords (40 tokens) weaken 执行, 完成, and task words;
首席执行 (chief executive) is also weaker. English counterparts are negative.
Separate rules approximate document-initial function words and two headers.
Other tokens predict zero. Context resets at each document boundary.
"""
import re
from functools import lru_cache
from opencc import OpenCC

READS = ()
_SIMPLIFY = OpenCC('t2s')

# This short lexicon distinguishes related expressions, not all synonyms.
CHINESE_ACTIONS = {
    '执': 7.6,        # grasp / execute (also a stem in "obstinate")
    '执行': 4.5,      # execute / carry out
    '执法': 2.1,      # enforce the law
    '行政执法': 2.1,  # administrative law enforcement
    '执着': 2.8,      # persist / be attached to
    '结束': 4.5,      # end / finish
    '结束了': 2.9,    # has ended
    '结束后': 1.8,    # after ending
    '完毕': 3.4,      # finish completely
    '完结': 2.0,      # conclude
    '完成': 1.05,     # complete / accomplish
    '已完成': 1.05,   # already completed
    '课题': 1.3,      # assigned problem / topic
}
TASK_WORDS = {'任务', '课题'}
COMPUTING = re.compile(
    r'代码|程序|函数|线程|进程|算法|模型|训练|同步|异步|超时|调用|'
    r'寄存器|编程|编译|计算机|脚本|控件|组件|'
    r'\b(?:sql|javascript|java|python|code|function|thread|async|js)\b',
    re.I,
)

# English grammatical words have a separate negative document-initial effect.
FUNCTION_WORDS = set('''
    a an the i we you he she it they me us him her them my our your his its
    their mine ours yours theirs this that these those who whom whose which
    what where why how in at on of to from for with without by about before
    after during between as into over under through and but or so if because
    when then than while although since until unless yet
'''.split())
AUXILIARIES = set('''
    can could may might must shall should will would do does did have has had
    is am are was were be been being
'''.split())


@lru_cache(maxsize=16000)
def word_value(token):
    word = _SIMPLIFY.convert(token.strip())
    if word in CHINESE_ACTIONS:
        return CHINESE_ACTIONS[word], word
    if '执行' in word:
        return 3.2, word
    if word.endswith('任务'):
        return 1.9, word
    english = word.lower()
    if re.fullmatch(r'execut(?:e|ed|ing|ion|ions|ive|ives|or|ors)', english):
        return -0.25, word
    if english == 'exec':
        return -0.22, word
    if english == 'finished':
        return -0.19, word
    if re.fullmatch(r'finish(?:es|ing)?|complet(?:e|ed|ing|ion)|'
                    r'accomplish(?:ed|ing)?|conclud(?:e|ed|ing)|'
                    r'terminat(?:e|ed|ing|ion)', english):
        return -0.09, word
    if token.startswith(' ') and re.fullmatch(r'end(?:s|ed|ing)?', english):
        return -0.08, word
    if english in ('task', 'tasks'):
        return -0.17, word
    return 0.0, word


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0, '')
    _, position, technical, previous = carry
    technical = max(0, technical - 1)
    if COMPUTING.search(token):
        technical = 40
    value, word = word_value(token)
    if word == '执行':
        if technical:
            value = 0.8
        elif '首席' in previous:
            value = 1.9
    elif word == '完成' and technical:
        value = 0.35
    elif (word in TASK_WORDS or word.endswith('任务')) and technical:
        value = 0.05
    if position == 0:
        english = token.strip().lower()
        if english in FUNCTION_WORDS:
            if token.startswith(' '):
                value = -0.15
            else:
                value = -0.5 if token[0].isupper() else -0.12
        elif english in AUXILIARIES and not token.startswith(' '):
            value = -0.7 if token[0].isupper() else 0.0
        elif token == '<|im_start|>':
            value = -0.25
    if position == 0 and token == '//\n':
        value = 4.42
    elif position == 1 and previous == 'Title' and token == ':':
        value = -4.025
    return (doc, position + 1, technical, token), float(value)

"""Signed spelling feature for Japanese ri and Chinese/Korean li/ri.

Positive: short Japanese ri endings, especially doubled consonants and
past-tense -tari ('doing such things as ...'). Negative: Mandarin third-tone li (li3)
characters and their short compounds, with related Sino-Korean spellings.
Other scripts have small rules for li spellings and Vietnamese l fragments.
Repeated middle-dot filler is positive. Most other tokens are zero. The
weights approximate training averages, not full pronunciation recognition.
"""
from functools import lru_cache
from pypinyin import lazy_pinyin, Style
import regex
import unicodedata

READS = ()


@lru_cache(maxsize=4096)
def is_li3(t):
    return len(t) == 1 and lazy_pinyin(t, style=Style.TONE3) == ['li3']


@lru_cache(maxsize=32768)
def han_value(t):
    if not regex.fullmatch(r'\p{Han}+', t):
        return 0.0
    if is_li3(t):
        return -2.8
    if t.endswith('公里'):
        return 0.0  # Kilometres, not a locative ending.
    # Locative/interior li endings; long lexicalized tokens are weaker.
    if t.endswith(('里', '裡', '裏')):
        return -3.0 if len(t) <= 2 else -1.6
    # Psychology, geography and physiology, respectively.
    if t.endswith(('心理', '地理', '生理')):
        return -3.5
    # The reason/order morpheme li in other compounds.
    if t.endswith('理'):
        return -0.7 if len(t) <= 2 else -0.2
    if t.startswith(('里', '裡', '裏')) and len(t) <= 3:
        return -1.1
    return 0.0


def spelling_value(s, previous):
    t = s.strip()
    if t.endswith(('り', 'リ')):
        if ((t in ('り', 'リ') and previous[-2:-1] in ('っ', 'ッ'))
                or (t in ('かり', 'くり', 'たり') and previous.endswith('っ'))):
            return 10.1 if t.endswith('リ') else 7.2
        if t.startswith('っ'):
            return 6.9
        if t == 'り':
            if previous.endswith(('た', 'だ')):
                return 5.7
            return 1.0
        if t == 'リ':
            return 2.1
        if t in ('たり', 'したり'):
            return 2.0
        if len(t) == 2:
            return 0.1
    c = han_value(t)
    if c:
        return c
    if t.startswith('리') and len(t) <= 2:
        root = previous[-1:]
        # Sino-Korean psychology/physiology/accounting, ethics/physics/order,
        # and logic/cuisine/management compounds, respectively.
        if root in ('심', '생', '경'):
            return -5.6
        if root in ('윤', '물', '조'):
            return -3.0
        if root in ('논', '요', '관'):
            return -1.3
        if root == '널':
            return 1.7
        return -0.7
    # Li assembled across token boundaries in several writing systems.
    if t in ('i', 'í', 'ǐ') and previous.endswith(('l', 'L')):
        return -0.3
    if t in ('ی', 'ي') and previous.endswith('ل'):
        return -1.6
    if t == 'і' and previous.lower().endswith('л'):
        return -0.5
    if t == 'ี' and previous.endswith(('ล', 'ร')):
        return -1.6
    if t in ('l', 'L', '-l'):
        # Horn vowels, hook-above and dot-below tones identify Vietnamese.
        marks = unicodedata.normalize('NFD', previous)
        if any(m in marks for m in ('\u031b', '\u0309', '\u0323', 'đ', 'Đ')):
            return -1.7
    if t == 'lý':
        return -3.1
    if t == 'Li':
        return -2.1
    if t == 'LI':
        return -0.3
    if t == 'li':
        return -0.4 if s[:1].isspace() else -0.2
    if t == '_li':
        return -0.4
    if t == 'lí':
        return -0.3
    if t == '··' and previous.endswith('··'):
        return 1.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = b'' if carry is None or carry[0] != doc else carry[1]
    b = prefix.token_bytes[-1]
    s = b.decode('utf-8', 'replace')
    previous = tail.decode('utf-8', 'replace')
    c = spelling_value(s, previous)
    if b and 0x80 <= b[0] < 0xc0:
        # A final UTF-8 fragment can complete one of the same characters.
        combined = (tail + b).decode('utf-8', 'replace')
        if combined and is_li3(combined[-1:]):
            c = -2.9
    return (doc, (tail + b)[-96:]), c

"""Document-opening templates with a small token-class background estimate.

Explicit positive spikes cover initial `Title:`, `12`, `int`, and a partial
Hangul lead byte. This is a partial approximation, not a full lexical model.
At other document starts, ordinary capitalized words tend negative and very
common English words tend positive; scripts have different starting offsets.
Inside text the estimate is much smaller, with negative offsets for Han text,
possessives and feminine pronouns. A few metadata phrases get their own values.
These broad classes deliberately leave token-specific variation unexplained.
