    until upon'''.split())
AUXILIARIES = frozenset('''be is am are was were been being have has had do
    does did will would can could shall should may might must'''.split())


def background(token, initial):
    word = token.strip()
    lower = word.lower()
    if word and len(word) >= 2 and set(word) == {'·'}:
        return -0.984  # Decorative dotted leaders.
    if initial:
        if word.isascii() and word.isalpha():
            value = -0.20
            if word.istitle() and not word.isupper():
                value -= 0.25
            if word.isupper():
                value += 0.15
            if zipf_frequency(word, 'en') >= 6:
                value += 0.40
            if token.startswith(' '):
                value += 0.08
