        if word.isdigit():
            return -0.036
        if token.isspace():
            return -0.18 if '\n' in token else -0.044
        for script, value in [('Katakana', -0.90), ('Hiragana', -0.35),
                              ('Han', -0.20), ('Hangul', 0.17),
                              ('Cyrillic', -0.06)]:
            if regex.search(r'\p{Script=' + script + '}', word):
                return value
        return 0.146 if token == '<|im_start|>' else -0.15
    if HAN.search(token):
        return -0.027
    if lower in {'she', 'her', 'hers', 'herself'}:
        return -0.046
    if lower in POSSESSIVES:
        return -0.023
    if lower in PREPOSITIONS:
        return -0.016
    if lower in AUXILIARIES:
        return -0.003
    if token.isspace():
        return -0.0015
    if word.isdigit():
        return -0.004
    if word and all(unicodedata.category(c).startswith('P') for c in word):
        return -0.005
    return -0.010


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, first, previous, recent = 0, '', '', ''
    else:
        _, position, first, previous, recent = carry
    token = prefix.token_strings[-1]
    value = background(token, position == 0)
    if position == 0:
        first = token
        if prefix.token_bytes[-1] == b'\xed':
            value = 2.094  # UTF-8 lead for late Hangul syllables.
        elif token == '<|endoftext|>':
            value = -1.538
        elif token == 'Title':
            value = -0.623
        elif token == 'int':
            value = 1.792
    elif position == 1:
        if first == 'Title' and token == ':':
            value = 4.163
        elif first == '1' and token == '2':
            value = 2.279
    if token == ' Level' and previous == ' Challenge':
        value = -0.125
    elif token == ' recorded' and previous == 'Comment':
        value = 0.080
    elif token == ' of' and re.search(r'\d+(st|nd|rd|th)$', recent):
        value = 0.185
    return (doc, position + 1, first, token, (recent + token)[-32:]), value

"""Approximate a negative response to the spelling 'ten' and its fragments.

Most informative is en... immediately after a token ending in t.  Short
preceding fragments and capital EN strengthen that response.  Some whole
word/stem spellings also respond, whereas most tokens are nearly zero.
Transliteration lets the same rules cover such spellings in other scripts.
There are small start-of-document offsets and a separate blank // comment
opener response.  This does not model the many word-specific exceptions.
"""
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=32768)
def spelling(token):
    return anyascii(token)


def response(token, previous, first):
    s, p = token.lower(), previous
    word = s.lstrip()
    boundary = (first or s != word or not p[-1:].isalpha()
