        return -4.5
    if word.startswith('pretend'):
        return -5.5 if word == 'pretend' else -3.2
    if word.startswith('attend'):
        return -0.72
    if word.startswith('ten'):
        if word == 'tend':
            return -2.36
        return -0.75

    if not s[:1].isspace():
        if p.endswith('t'):
            if s.startswith('en'):
                n = len(p.strip())
                size = 0 if n <= 2 else 1 if n <= 4 else 2
                if token.strip().isupper() and s in ('en', 'ens'):
                    return (-8.9, -4.5, -1.6)[size]
                if s == 'en':
                    return (-6.1, -2.95, -1.6)[size]
                return (-2.75, -2.33, -1.2)[size]
            if s.startswith(('in', 'an', 'em', 'n', 'es')):
                return -0.22
        if s.startswith('sten'):
            return -0.72
        if s.startswith('atten'):
            return -1.6
        if s.startswith('oten'):
