"""An orthographic ha/han-fragment detector, not a general topic detector.

Transliteration joins related spellings across scripts. Short fragments and
capitalized forms are stronger than longer words containing the same letters;
capitalization, spacing, and h-digraphs matter. Some script-specific spellings
(like Chinese Han) are especially strong, while Japanese particle は is weak.
UTF-8 fragments are handled incrementally. Small side rules capture laughter,
the opposite response to haste/hasty, doubled middle dots, and initial Title:.
Unrelated token-specific and finer contextual responses are left unmodeled.
"""
import codecs
import unicodedata
import regex
from anyascii import anyascii

READS = ()


def fragment_value(text, boundary):
    sound = anyascii(text).lower()
    if text in ('汉', '漢'):  # the Chinese Han characters
        return 7.6 if text == '汉' else 9.4
    if text == '呵呵':
        return 2.6
    if text == 'ห':  # Thai letter h
        return 3.1
    if text == '哈哈':
        return 5.2
    if text == '哈':
        return 3.5
    if text == '汗':
        return 3.8
    if text in ('韩', '韓'):
        return 1.8
    if regex.search(r'\p{Script=Han}', text):
        return 0.0
    if sound == 'han':
        if text == '한':
            return 6.8 if boundary else 3.0
        if text == 'ハン':
            return 1.6
        if boundary and text.islower():
            return 0.7
        if boundary:
            return 5.3
        return 4.5 if text == 'han' else 3.9
    if text.isascii() and regex.fullmatch('[aeiou]han', sound):
        return 4.0
    if sound == 'hans' and text[:1].isupper():
        return 2.8
    if text.isascii() and regex.fullmatch('[cks]han', sound):
        return 1.0
    if sound == 'ha':
        if text == 'は':
            return 0.04
        if text == 'ハ':
            return 1.85
        if text == '하':
            return 3.0 if boundary else 1.4
        if not text.isascii():
            accented = unicodedata.normalize('NFD', text)
            return 2.6 if '\u0300' in accented else 1.1
        if text.islower():
            return 0.55 if boundary else 0.8
        return 1.7 if boundary else 1.05
    if text == '함':
        return 3.1
    if sound == 'hae':
        return 2.1 if boundary else 1.2
    if text.isascii() and sound in ('aha', 'haha'):
        return 3.7
    return 0.0


