        value *= 1.6 if token in ('汉', '漢') else 1.3
    if token == '··':
        value = -2.18
    if position == 1 and previous == 'Title' and token == ':':
        value = 4.76
    return (doc, text, tail, position + 1), float(value)

"""A local digit-pair detector concentrated on the seventies and low eighties.

After 7, larger following digits give a more negative response. After 8,
small following digits give a negative response, fading by 87. Two smooth
curves approximate these responses, rather than memorizing individual pairs.
The response weakens inside longer digit strings. It also partly carries
across decimal points and commas, and much less across other separators.
Other tokens receive zero; unrelated lexical responses are not modeled.
"""

READS = ()


def digit(s):
    return len(s) == 1 and '0' <= s <= '9'


def response(tens, unit):
    if tens == '7':
        return -1.36 * unit + 0.066 * unit * unit
    distance = max(0, 7 - unit)
    return -1.17 * distance + 0.080 * distance * distance


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        run = age = 0
    else:
        _, run, age = carry
    s = prefix.token_strings[-1]
    run = run + 1 if digit(s) else 0
    previous = prefix.token_strings[-2] if age >= 1 else ''
    before = prefix.token_strings[-3] if age >= 2 else ''
    value = 0.0
    if digit(s):
        tens = previous
        scale = 1.0 if run == 2 else 0.82 if run < 5 else 0.76
        if previous not in ('7', '8'):
            tens = before
            if previous == '.':
                scale = 0.64 if tens == '7' else 0.52
            elif previous == ',':
                scale = 0.42 if tens == '7' else 0.28
            elif previous == ':':
                scale = 0.18 if tens == '7' else 0.13
            elif previous in ('-', '/'):
                scale = 0.08 if tens == '7' else 0.05
            elif previous == ' ':
                scale = 0.07 if tens == '7' else 0.045
            else:
                scale = 0.0
        if tens in ('7', '8'):
            value = scale * response(tens, int(s))
    return (doc, run, age + 1), value

