"""Layer-1 MLP down-projection, component 3619.

What it responds to: the word right after a coordinating conjunction ("and", "or",
"et", "than"), when that word is a preposition that links the second item of the pair:
"and [of]", "or [de]", "et [de]", "and [to]", "than [in]". "of"-type prepositions
(of, de, to, from, by) drive it hardest; a comma before them gives a weaker push.
Negative at the first token of each document (the token after <|endoftext|>, or the
first token of a row), and strongly negative inside a run of middle dots (·).
Everything else is about zero."""

READS = ()

CONJ = {"and", "or", "et", "than", "ou", "nor"}
WEAK_CONJ = {"but", "y", "e"}
OF_LIKE = {"of", "de", "to", "from", "by", "du", "à"}
PREPS = {"in", "on", "for", "with", "as", "at", "through", "over", "about", "into"}
ARTICLES = {"a", "an", "the", "la", "le", "les", "en", "da"}
AUX = {"is", "are", "was", "were", "be", "been", "have", "has", "had", "can", "will",
       "would", "should", "could", "may", "might", "must"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1].strip().lower()
    if prefix.position == 0 or toks[-2] == "<|endoftext|>":
        return None, 0.0 if cur == "<|im_start|>" else -0.45
    if cur and set(cur) == {"·"}:
        return None, -2.0
    prev = toks[-2].strip().lower()
    scale = 1.0 if prev in CONJ else 0.5 if prev in WEAK_CONJ else 0.0
    if scale > 0:
        if cur in OF_LIKE:
            return None, 1.8 * scale
        if cur in PREPS:
            return None, 1.1 * scale
        if cur in ARTICLES:
            return None, 0.4 * scale
        if cur in AUX:
            return None, 0.5 * scale
        return None, 0.0
    if prev == ",":
        if cur in OF_LIKE:
            return None, 0.8
        if cur in PREPS:
            return None, 0.3
    return None, 0.0

