            r'(?:[aeu]?n?|in)c(?:[eisy]|e[sd]|ing|er[s]?)?', t)
        if continuation and p.endswith('l') and len(p.strip()) <= 6:
            value = 1.5 if len(t) <= 3 else 1.0
            if t.startswith('u') or t.startswith('enc') and t != 'enc':
                value = 0.2
            if p.endswith('gl') and t.startswith('anc'):
