    elif word == 'lc':
        value = 2.2
    elif re.fullmatch(r'g?lanc(?:e[ds]?|ing)?', s.strip().lower()):
        value = 2.5 if s.strip().startswith('L') else 3.1
    elif re.fullmatch(r'p?lac', word):
        value = 1.3

