    marker = previous.strip()
    comment = marker in {'*', '//', '#', '/*', '/**', '##'}
    comment = comment or bool(re.search(r'(//|/\*|#)\s*$', tail))
    if s.strip() in {'Copyright', 'Licensed'} and comment:
        value = 3.6
        if s.strip() == 'Copyright':
            value = 10.0 if marker in {'*', '/*', '/**'} else 8.0
            if marker in {'#', '##'}:
                value = 5.5
