"""Concept program for layers.1.mlp.down_proj:3621, one MLP neuron in layer 1.

It is quiet almost everywhere. Its large values come from a few readable cases:
  * the letter c right after an l, as in "miscal|c|ulation" or the all-caps "CAL|C|ULATE":
    strongly positive (c after l, and C after L in an all-caps word);
  * the pieces lc, lec, clc, alc and the words PLC, glance, lance, Licensed: positive;
  * "Copyright" opening a source-code comment (after //, #, /*, or a leading *): strongly positive;
    the same word in running prose is about zero;
  * c-sound pieces ci, ac, nc: weakly positive;
  * Turkish suffix pieces (-lık, -lik, -luk, -ilik, -ığı, ...) and the letter ğ: negative,
    and the piece "uk" weakly negative;
  * the first token of a document, which has no preceding context: slightly negative.
Values are typical activations of each class, not fitted per token.
"""
READS = ()

COMMENT_MARKS = ("//", "#", "/*", "*")
C_AFTER_L_PIECES = {"lc", "lec", "clc", "alc"}
C_WORDS = {"PLC", "LC", "glance", "lance", "Licensed", "plac"}
C_SOUND_PIECES = {"ci", "ac", "nc"}
TURKISH_SUFFIX = {
    "lik", "lık", "luk", "lük", "lick", "ilik", "ilık", "liğe", "luğu", "üğü",
    "ığı", "ği", "ığ", "ık", "ğ", "ıkl",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, -0.2
    before = prefix.token_strings[-2].strip()[-1:]
    if word == "c" and before == "l":
        return carry, 3.0
    if word == "C" and before == "L":
        return carry, 4.4
    if word in ("c", "C") and before in ("l", "L"):
        return carry, 0.8
    if word == "Copyright":
        recent = prefix.token_strings[-4:-1]
        in_comment = any(mark in s for s in recent for mark in COMMENT_MARKS)
        return carry, (7.0 if in_comment else -0.3)
    if word in C_AFTER_L_PIECES or word in C_WORDS:
        return carry, 2.0
    if word in C_SOUND_PIECES:
        return carry, 0.5
    if word in TURKISH_SUFFIX:
        return carry, -1.6
    if word == "uk":
        return carry, -0.3
    return carry, 0.0

