"""Estimate breaks in unfinished phrases from word classes and typography.

Bare newlines are strongest after continuation-requiring words and on word-rich
recent lines. Most word-containing tokens predict zero. Document-opening Title:,
HTML and empty comment markers, and pure middle-dot filler, have separate rules.
The bounded text history resets at document boundaries; this is not a parser.
"""
import calendar
import re
from functools import lru_cache
import wordnet

READS = ()

# Name, continuation strength, and the closed-class words in that class.
GRAMMAR = (
    ('definite article', 1.33, 'the'),
    ('indefinite article', .97, 'a an'),
    ('possessive', .93, 'my your his her its our their'),
    ('determiner', .85, 'this that these those each every any some no another such'),
    ('code literal', 0., 'true false null none pass break continue'),
    ('abbreviation', 1.19, 'mr mrs ms dr prof sr jr rev st mt no vs etc '
                          + ' '.join(calendar.month_abbr[1:]).lower()),
    ('preposition', 1.14, 'of in on at by for from to with without into onto upon '
                        'about between among through during under over than as per'),
    ('conjunction', 1.26, 'and or but nor'),
    ('subordinator', .74, 'if because although while whether which whose when where'),
    ('modal', .87, 'can could will would shall should may might must'),
    ('auxiliary', .83, 'is are was were be been being am has have had do does did'),
    ('pronoun', .78, 'i you he she it we they who whom'),
    ('foreign article', 1.51, 'der die das den dem des le la les el los las '
                             'il lo gli het'),
    ('foreign preposition', 1.02, 'de du en dans pour par sur au aux von zu zum '
                                 'zur mit nach bei aus auf über unter del con '
                                 'por para sin sobre entre'),
    ('foreign conjunction', .72, 'et und oder ou que qui y'),
