                for name, value, words in GRAMMAR)


@lru_cache(maxsize=32768)
def word_strength(word):
    word = word.lower()
    for name, value, words in GRAMMAR:
        if word in words:
            return value
    pos = wordnet.parts_of_speech(word)
    if 'adjective' in pos:
        return .51 if 'noun' in pos else .72
    if 'adverb' in pos:
        return .57
    if 'verb' in pos:
        return .32 if 'noun' in pos else .65
    if 'noun' in pos:
        return .26
