        return 1.62
    if any(text.endswith('<|im_start|>' + role)
           for role in ('assistant', 'user', 'system', 'tool')):
        return 0.
    if text.endswith(('<tool_call>', '<tool_response>', '<think>')):
        return .84
    if text.endswith(('</tool_call>', '</tool_response>', '</think>')):
        return .18
