    if bare in ('(', '[', '{'):
        return .06, .28
    if bare in (')', ']', '}'):
        return -.01, .08
    if bare in ('`', '``', '```'):
        return -.04, .04
    if bare in ('"', "'", '“', '”', '‘', '’'):
        return 0., .03
    if newline:
        return .02, .25
    if bare in ('/', '//', '\\'):
        return .04, .38
    if bare in ('-', '–', '—', '‐'):
        return -.01, .18
    if bare in ('<', '>'):
        return -.03, .16
    if bare in ('#', '##', '###'):
