            baseline, sensitivity = -.01, 1.
            if history.rstrip()[-1:].isalpha():
                words = len(history.rsplit('\n', 1)[-1].split())
                group = (0 if words == 0 else 1 if words == 1 else 2 if words < 5
                         else 3 if words < 10 else 4 if words < 20 else 5)
                strength *= (.05, .72, .47, 1.19, 1.65, 2.47)[group]
        elif '\t' in token:
            baseline, sensitivity = 0., .62
        else:
            baseline, sensitivity = (0., .07) if token == ' ' else (.05, .48)
    elif escaped:
        baseline, sensitivity = .12, .80
    else:
        baseline, sensitivity = punctuation_response(bare, '\n' in token)
    return updated, baseline - sensitivity * strength

programs.haiku:
"""Layer 1, MLP down_proj, component 3622.

What it responds to: a line break (or an ellipsis) that cuts a phrase off before it is
finished, so the text has to continue. The component is negative there:
  * a line break right after a function word such as "the", "of", "and", "to", "is"
    (-1.1);
  * a line break right after dangling punctuation (a comma, dash, plus sign) (-0.6);
  * a line break right after a chat or tool tag such as <|im_end|>, <think>,
    <tool_call> (-1.0);
  * an ellipsis "..." or "…" (-0.6);
  * a line break after an ordinary word (-0.09); after a finished sentence,
    a digit or a symbol (-0.02).
Repeated middle-dot leaders ("····") are a rare large positive outlier, seen in one
document of the training sample.
Everything else predicts 0.

The program needs only the current token and the one before it.
"""

READS = ()

FUNCTION_WORDS = {
    "the", "a", "an", "of", "and", "to", "in", "on", "at", "by", "for", "with", "from",
    "or", "as", "be", "is", "are", "was", "were", "that", "which", "its", "this", "than", "it",
}
DANGLING = {",", "-", "—", "–", "+", "'", "/", "("}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok and set(tok) == {"·"}:
        return None, 1.6
    if tok.strip() in ("...", "…", ".."):
        return None, -0.6
    if "\n" in tok or "\r" in tok:
        word = prev.strip().lower()
        if word in FUNCTION_WORDS:
            return None, -1.1
        if word in DANGLING:
            return None, -0.6
        if prev.endswith(">"):
            return None, -1.0
        if word[-1:].isalpha():
            return None, -0.09
        return None, -0.02
    return None, 0.0

programs.sol:
"""Recognize local programming and scraped-page boilerplate.

This is a collection of literal, recognizable collocations, not a general
semantic detector. Java method modifiers give a positive response at `void`;
Git patch headers and several fixed comment/markup fragments give negative
responses. Initial whitespace and numbers get small formatting defaults.
Unrecognized text is predicted near zero. The short text buffer
is reset at each document boundary.
"""
import re

READS = ()

# Complete fixed fragments in generated code and downloaded web pages.
# Each pair is (preceding token, current token); values are training means.
COLLOCATIONS = {
    ("--", "git"): -8.2,                 # Git patch header
    ("-user", "-doc"): -9.9,           # begin/end-user-doc comments
    ("Download", "ed"): -2.0,          # Downloaded package logs
    ("Created", "by"): -4.3,           # source-file author comment
    ("Last", "edited"): 1.8,           # forum edit notice
    ("[#", "permalink"): -1.7,         # forum permanent-link marker
    ("email", "protected"): -1.3,      # redacted email address
    ("Google", "Scholar"): -1.6,       # citation link
    ("shows", "pages"): -1.6,          # document preview notice
    ("firstname", ".lastname"): 0.8,   # placeholder email address
    ("Record", "<string"): -0.8,       # TypeScript generic type
    ("script", "src"): -2.2,           # external script tag
    ("script", "-src"): -1.8,          # content-security policy
    ("param", "name"): 0.8,            # XML documentation parameter
    ("@@", "-"): -0.6,                # patch hunk header
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    if fresh:
        previous, recent = "", ""
    else:
        _, previous, recent = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    before = previous.strip()
    value = COLLOCATIONS.get((before, word), 0.003)
    if fresh:
        if token.isspace():
            value = 0.47
        elif word.isdecimal():
            value = 0.15
        elif token == r"\n":
            value = 1.13
        elif token == r"\t":
            value = 2.67

    if word == "void":
        if before == "static":
            value = 4.0 if re.search(r"\bpublic\s+static$", recent) else 1.1
        elif before in {"public", "private", "protected"}:
            value = 1.3
    elif word == "string" and before in {"doc", "/doc", "_doc"}:
        value = -2.6
    elif word in {"begin", "end"} and before.endswith("<!--"):
        value = -1.8
    elif word in {"em", "title"} and before.endswith("<"):
        value = -1.1
    elif word == ")" and re.search(r"Copyright\s*\([cC]$", recent):
        value = -5.1 if recent.endswith("c") else -1.3
    elif word == "©" and before == "Copyright":
        value = -0.7
    elif word.lower() == "utf" and re.search(r"coding\s*:$", recent):
        value = -3.6
    elif word == "from" and recent.endswith("Downloaded"):
        value = -3.8
    elif word == "document" and before == "$(":
        value = -1.0
    elif word == "</tool_call>":
        value = 0.23
    # Repeated middle-dot filler, as in separator/leader text.
    elif word and set(word) == {"·"} and before and set(before) == {"·"}:
        value = 0.895

    return (doc, token, (recent + token)[-100:]), value

"""A document-initial pulse, with amplitude estimated from token type.

It persists if the opening token is repeated unchanged, then switches off.
Subject pronouns, auxiliaries and other grammar words weaken or reverse
it. Uncommon, capitalized Latin fragments tend to have larger pulses.
Script, digits and punctuation supply coarse fallbacks. These rules
approximate lexical amplitudes rather than memorizing individual tokens.
"""
import regex
from wordfreq import zipf_frequency
DETERMINERS = set(
    'a an the each every some any all both either neither another other'.split()
)
DEMONSTRATIVES = set('this that these those'.split())
BE = set('am is are was were be been being'.split())
AUXILIARIES = set(
    'do does did can could may might must shall should will would'.split()
)
CONNECTIVES = set(
    'and or but nor so if as than then unless although though '
    'because while whether yet'.split()
)
NEGATION = set('not no never neither'.split())
PREPOSITIONS = set(
    'to of for from in on at by with without about into onto over under '
    'through during between among against per via'.split()
)

READS = ()

def initial_value(text):
    word = text.strip()
    lower = word.lower()
    capital = word.istitle()
    if text.startswith('<|') and text.endswith('|>'):
        return 6.0
    if not word:
        if set(text) == {'\t'}:
            return -4.5
        if '\t' in text:
            return 4.0
        return 6.0 if len(text) > 1 and not '\n' in text else 3.3
    # Subject and object pronouns have different opening-token behavior.
    if lower == 'they':
        return -13.0
    if lower in {'he', 'she', 'it'}:
        return -8.0
    if lower in {'i', 'we'}:
        return -2.0
    if lower in {'me', 'us', 'him', 'her', 'them'}:
        return 3.0
    if lower == 'you':
        return 2.0 if capital else -2.0
    if lower in {'who','whom','whose','what','which'}:
        return -7.5
    if lower in {'when','where','why','how'}:
        return -4.5
    if lower in {'only','just','also','merely','solely'}:
        return -6.5
    if lower in {'always','never'}:
        return -6.5
    if lower in {'there','here'}:
        return -7.0
    if lower.startswith(("'", '’')) and lower[1:] in {'s','t','re','ve','m','d','ll'}:
        return -4.0
    if regex.fullmatch(r'(some|any|every|no)(one|body|thing)', lower):
        return -4.5
    if lower in NEGATION:
        return -4.5
    if lower in BE and not word.isupper():
        return -3.0
    if lower in DEMONSTRATIVES:
        return -4.5
    if lower in DETERMINERS:
        return 1.0 + 2.0 * capital
    if lower in {'has','have','had'}:
        return -4.5
    if lower in AUXILIARIES or lower == 'cannot':
        return 1.0 + capital
    if lower in CONNECTIVES:
        return 1.0
    if lower in PREPOSITIONS:
        value = 6.5 if lower in {'in','on','at','for'} else 3.5
        return value + 3.0 * capital
    if word.isdecimal():
        return 5.3 if word != '0' else -0.3
    if '\ufffd' in word:
        return 3.0
    if not any(c.isalpha() for c in word):
        if word[0] in ')]}':
            return 0.0
        if word[0] in '([{':
            return 5.0
        if word.startswith('#'):
            return 6.8
        return 2.8
    if regex.search(r'\p{Script=Cyrillic}',word):
        return 9.0
    if regex.search(r'\p{Script=Han}',word):
        return 4.8
    if not regex.search(r'\p{Script=Latin}',word):
        return 5.0
    return content_value(word)

def content_value(word):
    # English corpus commonness is a rough proxy for lexical specificity.
    frequency = zipf_frequency(word.lower(), 'en')
    return (8.0 - 1.5 * max(0.0, frequency - 3.0)
            + 3.5 * word.istitle() + word.isupper())

def step(carry, prefix, upstream):
    token = prefix.token_ids[-1]
    doc = prefix.document_ids[-1]
    # A different token ends the initial run; document boundaries reset it.
    if carry is None or carry[0] != doc:
        active = True
    else:
        active = carry[2] and carry[1] == token
    value = initial_value(prefix.token_strings[-1]) if active else 0.0
    return (doc, token, active), value

programs.haiku:
"""Document-start detector for one MLP down-projection component.

What it does: this component is nearly silent inside ordinary text. It fires at the first
token of each document (the model has no earlier text to look back at), and it also fires
on any token that has repeated since the document start, where attention only sees copies
of that token. Its size then depends on the token alone:

  - pronouns, wh-words, negation and frequency adverbs ("They", "What", "never", "这", "什么")
    push it strongly negative;
  - auxiliaries and copulas ("is", "be", "my") sit near zero;
  - determiners, prepositions and conjunctions ("the", "of", "and") are small and positive;
  - punctuation is low, digits and ordinary words are moderate;
  - capitalised names, Cyrillic and Arabic words, and Chinese place and institution words
    ("市", "省", "网") are the most positive.

So the program: if the document so far is a single repeated token, output that token's value;
otherwise output 0.
"""

READS = ()

LOW_WORDS = set("""it they he she this that these those there what which who whom where when why how
nothing nobody no not none never nowhere someone something somebody anyone anything everyone
everything always often sometimes really actually already suddenly barely ever""".split())
AUX_WORDS = set("""is am are was were be been being do does did have has had can could will would
shall should may might must my your his her our their its one""".split())
SMALL_WORDS = set("""the a an of to in on at for with by from as and or but if so than then
because while about into over under also just very too all some any each both""".split())
CN_LOW_CHARS = "这什没他它但也是我甚啥"
CN_HIGH_CHARS = "市省网国学县区"


def word_value(s):
    t = s.strip()
    w = t.lower()
    if t == "":
        return 3.0
    if any("一" <= c <= "鿿" for c in t):
        if any(c in CN_LOW_CHARS for c in t):
            return -4.0
        if any(c in CN_HIGH_CHARS for c in t):
            return 9.0
        return 5.0
    if any("Ѐ" <= c <= "ӿ" or "؀" <= c <= "ۿ" for c in t):
        return 10.0
    if w in LOW_WORDS:
        return -7.0
    if w in AUX_WORDS:
        return -1.0
    if w in SMALL_WORDS:
        return 3.0
    if t.isascii() and t.isalpha():
        return 9.0 if t[0].isupper() else 6.0
    if t.endswith((".", ",", ")", '"', "'", ":", ";", "!", "?")):
        return 2.5
    if any(c.isdigit() for c in t):
        return 4.0
    return 5.0


def step(carry, prefix, upstream):
    tok = prefix.token_ids[-1]
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc or carry is None:
        first, uniform = tok, True
    else:
        first, uniform = carry[0], carry[1] and tok == carry[0]
    carry = (first, uniform)
    if not uniform:
        return carry, 0.0
    return carry, float(word_value(prefix.token_strings[-1]))

programs.sol:
"""An io spelling detector, strongest around iot, and negative for iu.

Short word pieces and vowel pairs crossing a token boundary get the largest
responses. Long pieces get smaller responses. Latin-letter transliterations
also recognize the pattern in alphabetic scripts, but not in CJK readings.
Most constants are rounded training averages for these spelling categories.
Two fixed continuation values cover io+t and io+ch across more than two pieces.
"""
from functools import lru_cache
import regex
from anyascii import anyascii

@lru_cache(maxsize=65536)
def roman(word):
    if regex.search(r'[\p{Han}\p{Hiragana}\p{Katakana}\p{Hangul}]', word):
        return word.lower()
    return anyascii(word).lower()

@lru_cache(maxsize=32768)
def response(previous, token):
    before, text = roman(previous), roman(token)
    word, size = text.lstrip(), len(text.lstrip())
    previous_size = len(before.strip())
    # Cross-piece vowel sequences.
    if before.endswith(('i', 'y')) and text.startswith('ot'):
        return 4.31 if size <= 3 else 1.15
    if 'iot' in word:
        if len(word) - word.index('io') > 4:
            return 0.57
        if word.startswith('iot') and token == token.lstrip():
            return 8.43
        if word.startswith('rio'):
            return 7.06
        return 1.81
    if before.endswith('i') and text.startswith('u'):
        if previous.isupper():
            return -1.98
        if size == 1:
            return -2.71
        return -1.65 if size <= 3 else 0.02
    if before.endswith(('i','y')) and text.startswith('o'):
        if size == 1:
            return 2.13 if previous_size <= 4 else 0.0
        return 1.11 if size <= 3 else 0.68
    # Sequences contained in a single word piece.
    if word.startswith('iu') and not word.startswith('ium'):
        return -2.35 if size == 2 else -0.88
    if word.startswith('iol'):
        return 3.89 if size <= 4 else 0.61
    if word.startswith('vio'):
        return 3.1 if size <= 4 else 0.34
    if word.startswith('io'):
        if word.startswith('ion'):
            return 0.3
        if size <= 3:
            if before.endswith(('l','v','t')):
                return 1.67
            return 0.9
        return 0.21
    if 'io' in word:
        if size <= 4:
            return 0.61
        return 0.01
    # A little of the response can persist into the next word piece.
    if before.endswith('iot') and previous_size <= 5 and text[:1].isalpha():
        return 2.05
    if before.endswith('io') and previous_size <= 4 and text[:1].isalpha():
        return 0.3
    return 0.0


READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    token = prefix.token_strings[-1]
    text = roman(token)
    value = response(previous, token)
    # Complete io+t even when i, o, and t occupy separate tokens.
    if (tail.endswith('io') and len(roman(previous).strip()) <= 4
            and text.startswith('t')):
        value = 5.0
    elif (tail.endswith('io') and len(roman(previous).strip()) <= 4
          and text.startswith('ch')):
        value = 2.5
    return (doc, token, (tail + text)[-3:]), float(value)

"""Surface cues for durations, activity modifiers, and generic entity nouns.

Negative values mark duration partitives ("years of"), thorough or intensive
activity modifiers, and the first digit after a numeric colon. Generic noun
heads have weaker positive offsets. These are weighted text cues, not a full
parser. Ending, Chinese grammatical-marker, and document-start rules cover
additional regularities; much context-dependent variation remains unexplained.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
# Coherent semantic groups, not lists of token ids.
PROCESS_MODIFIERS = set('''thorough detailed systematic methodical meticulous careful
rigorous exhaustive comprehensive extensive intensive in-depth concerted targeted
deliberate purposeful mutual collaborative coordinated sustained painstaking
vigorous active preliminary simultaneous continuous continual'''.split())
TEMPORAL = set('''previous prior earlier recent initial preliminary latest continued
ongoing constant repeated temporary permanent long short gradual immediate
subsequent successive frequent occasional prolonged lengthy brief'''.split())
EXTENT = set('''full complete actual proper exact substantial considerable massive
deep complex broad extensive slight rich'''.split())
ACTIVITY_NOUNS = set('''discussion deliberation consultation conversation collaboration
investigation examination calculation trial visit review experiment negotiation
rehearsal exploration'''.split())
OBJECT_HEADS = set('''entity entities item items object objects thing things
creature creatures organism organisms substance substances material materials'''.split())
POPULATIONS = set('''people population populations country countries nation nations
city cities species animal animals'''.split())

THOROUGHNESS = set('''thorough detailed systematic methodical meticulous
exhaustive painstaking in-depth'''.split())
PARTITIVES = set('''lot plenty multitude mass touch dash piece bunch combination
mix mixture sense feeling matter policy game bout spell phase'''.split())
REQUIRES = set('''need needs require requires requiring required despite after
without almost'''.split())
TIME = set('''second minute hour day week month year decade century millennium
moment period interval episode generation round iteration'''.split())
CHINESE_TIME = re.compile(
    r'[零一二三四五六七八九十百千万两0-9]+'
    r'(?:[个個]?月|年|周|天|日|小时|小時|分钟|分鐘)$'
)

# Per class: ordinary use, after a/an, after a requirement/temporal cue.
CLASSES = (
    (PROCESS_MODIFIERS, -0.44, -0.29, -0.69),
    (TEMPORAL, -0.17, -0.31, -0.53),
    (EXTENT, -0.10, -0.21, -0.14),
    (ACTIVITY_NOUNS, -0.13, -0.18, 0.0),
    (OBJECT_HEADS, 0.17, 0.19, 0.0),
    (POPULATIONS, 0.065, 0.22, 0.0),
)
SUFFIXES = {'ous': -0.08, 'ful': -0.12, 'ual': -0.07, 'ive': -0.02}
FRAGMENTS = {'ious': -0.25, 'ous': -0.25, 'eous': -0.25,
             'ful': -0.40, 'ual': -0.31, 'ive': -0.10,
             'ative': -0.10, 'itive': -0.10}

@lru_cache(maxsize=32768)
def describe(text):
    word = text.strip().lower()
    whole = text.startswith(' ') and bool(re.fullmatch('[a-z]+', text.strip()))
    bases = wordnet.base_forms(word, 'noun') if whole else ()
    unit = next((b for b in bases if b in TIME), '')
    adjective = whole and 'adjective' in wordnet.parts_of_speech(word)
    return word, whole, unit, adjective, bases


def duration_of(unit, plural):
    if unit == 'period':
        return -1.8 if plural else -1.6
    if unit in ('moment', 'round'):
        return -1.4 if plural else -0.9
    if unit in ('episode', 'generation', 'iteration', 'interval'):
        return -0.8 if plural else -0.4
    if unit in ('second', 'minute'):
        return -1.0 if plural else -0.4
    if unit in ('hour', 'day'):
        return -1.5 if plural else -0.55
    return -2.0 if plural else -0.8


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0)
    _, previous, before, position = carry
    text = prefix.token_strings[-1]
    word, whole, unit, adjective, bases = describe(text)
    pw, _, previous_unit, previous_adj, previous_bases = describe(previous)
    article = pw in ('a', 'an')
    requirement = pw in REQUIRES
    quantifier = pw in ('some', 'several', 'much')
    value = 0.0
    if whole:
        for words, base, after_article, after_requirement in CLASSES:
            if word in words:
                value += base + article * after_article
                value += requirement * after_requirement
        if word in THOROUGHNESS:
            value -= 0.25
        if previous_adj and word in OBJECT_HEADS | POPULATIONS:
            value += 0.16
        if adjective:
            value -= 0.04 * article + 0.22 * requirement
        for ending, weight in SUFFIXES.items():
            if len(word) > len(ending) + 2 and word.endswith(ending):
                value += weight
        if unit:
            value -= 0.16 * word.endswith('s') + 0.18 * article
            value -= 0.48 * requirement + 0.18 * quantifier
        if word in ('some', 'several', 'much'):
            value -= 0.16 + 0.07 * article + 0.93 * requirement
        if word in ('a', 'an') and requirement:
            value -= 0.36
        if word == 'series':
            value -= 0.20
        if word == 'ago':
            value += 0.40
        if word == 'old' and previous_unit:
            value += 0.52

    if text == ' of':
        value = -0.01
        if previous_unit:
            value = duration_of(previous_unit, pw.endswith('s') or pw == 'centuries')
        elif pw in ('bit', 'series'):
            value = -1.3
        elif pw in PARTITIVES or any(b in PARTITIVES for b in previous_bases):
            value = -0.45
    if len(text) == 1 and text in '0123456789' and previous == ':' and before.isdigit():
        value -= 0.38
    if text == '的':
        value -= 0.26
        if CHINESE_TIME.search(before + previous):
            value -= 0.95
    if text.endswith(('年的', '个月的', '個月的')):
        value -= 0.95
    if text in ('年', '次'):
        value -= 0.21 if text == '年' else 0.53
    value += FRAGMENTS.get(text, 0.0)
    if text in ('ных', 'ной', 'ная', 'ный', 'ные', 'ную', 'ным',
                'ного', 'ное', 'скому', 'ская', 'ские'):
        value -= 0.17
    if text in ("'s", '’s'):
        value -= 0.02 + 0.10 * bool(previous_unit)
    if len(text) > 1 and set(text) == {'·'}:
        value += 0.35

    if position == 0:
        value += 0.14 + 0.14 * text.strip().istitle()
        if text.startswith(' ') and text.strip().isalpha():
            value += 0.04
        if len(text) == 1 and text in '0123456789':
            value -= 0.12
        if text == 'package':
            value += 1.44
    if position == 1:
        value += 0.02
    if text == ':' and previous == 'Title' and position < 3:
        value += 4.9
    return (doc, text, previous, position + 1), float(value)

"""A heuristic typesetting-boundary signal, not a calculation of mathematics.

Opening math delimiters, display-style commands, and math environments get
positive pulses. Nearby price and code cues weaken dollar pulses;
closing dollars are weak or negative. Secondary rules cover headings,
repeated middle dots, and dense backtick markup with nonbreaking spaces.
The state is just the last 160 characters of the current document.
"""
import re

READS = ()


def typesetting_pulse(s, before):
    stripped = s.strip()
    if len(stripped) >= 2 and set(stripped) == {'·'}:
        return 2.0
    if '`' in s and '\xa0' in before and before.count('`') >= 5:
        if stripped.endswith('`') and len(stripped) <= 2:
            return -0.7
    if '$' in s:
        if stripped == '$' and '$' in before:
            left, formula = before.rsplit('$', 1)
            words = re.sub(r'\\[A-Za-z]+', '', formula)
            if (left.endswith((' ', '\n')) and len(formula) < 80
                    and re.search(r'[_^\\]', formula)
                    and not re.search(r'[A-Za-z]{3,}', words)):
                return -0.3
        if before.endswith('$') and s.startswith('$'):
            return 2.9
        at = s.find('$')
        left = before + s[:at]
        opening = not left or left[-1].isspace() or left[-1] in '([{'
        # A dollar attached to an expression is normally its closing marker.
        if not opening:
            return 0.1 if s[-1:] in ',.\n' else -0.3
        if '\\' in s:
            return 3.2
        if stripped.startswith('$$'):
            return 2.9
        if not before and s.startswith(' $'):
            return -2.1
        # Dollars also introduce code variables and monetary amounts.
        line = before.rsplit('\n', 1)[-1]
        if (re.search(r'\$\w+->|=>|<\?php|\bfunction\s+\w*\s*\('
                      r'|\b(?:foreach|isset|echo)\b',
                      before[-120:])
                or re.search(r'(?:=|\(|\breturn)\s*$', line)
                or (len(line) >= 3 and not line.strip())):
            return 0.0
        if re.search(r'[^\s$]\$(?:[.,;:!?)]|\s|$)', before) or re.search(
                r'\\(?:frac|sqrt|sum|prod|int|math\w*|left|right|'
                r'alpha|beta|gamma|delta|theta|lambda|sigma|pi|begin|end)\b'
                r'|\^|_[A-Za-z{]', before):
            return 2.4
        if re.search(r'\$\s*\d[^$]*$', before):
            return -0.1
        if re.search(r'\b(?:price|cost|paid|pay|cash|money|dollars?|worth|'
                     r'priced|valued|sell|buy|spend|fined|billion|million)\b',
                     before[-120:], re.I):
            return 0.9
        if re.search(r'\b(?:let|if|that|where|then|denote|suppose|given|'
                     r'set|is|of|the)\s*$', before, re.I):
            return 2.0
        return 0.9
    if '\\(' in s:
        return 3.5
    if '\\[' in s:
        line_start = not before.rsplit('\n', 1)[-1].strip()
        return 5.6 if line_start else 1.0
    if before.endswith('\\') and stripped.startswith(('(', '[')):
        if stripped[0] == '[':
            line = before.rsplit('\n', 1)[-1].rstrip('\\ ')
            return 5.6 if not line else 1.0
        return 3.5
    if '\\' in s:
        if not s.rstrip().endswith('\\'):
            return 0.0
        if before.endswith('$$'):
            return 2.0
        if before.endswith('$') or before.endswith('\\displaystyle'):
            return 1.0
        return 0.1
    # LaTeX control words may span several tokenizer pieces.
    command = re.search(r'\\([A-Za-z]*)$', before)
    if command and s.isalpha():
        name = command[1] + s
        if name in ('displaystyle', 'textstyle'):
            return 5.1
        if name == 'display':
            return 3.6
        if name.startswith(('left', 'big', 'Big')):
            return 1.3
        if name in ('large', 'Large', 'huge', 'Huge'):
            return 1.3
        if name in ('leq', 'geq') and s == 'q':
            return 1.1
        if name.startswith('right'):
            return 0.3
        if name == 'begin':
            return 0.7
        return 0.0
    environment = re.search(r'\\(begin|end)\{([A-Za-z*]*)$', before)
    if environment and re.fullmatch(r'[A-Za-z*} \n]+', s):
        name = environment[2] + s.rstrip('} \n')
        environments = ('equation', 'eqnarray', 'align', 'aligned',
                        'gather', 'multline', 'displaymath', 'math')
        if name and any(e.startswith(name.rstrip('*')) for e in environments):
            if environment[1] == 'end':
                return 0.4
            if s == '*':
                return 0.0
            return 4.7 if '}' in s else 5.0
    if stripped == '##':
        return 0.8 if s.startswith(' ') else 0.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = typesetting_pulse(s, before)
    text = '' if '<|endoftext|>' in s else (before + s)[-160:]
    return (doc, text), value

programs.haiku:
"""Layer 1 MLP down-projection, component 3632: a "hard K sound" detector.

In plain terms: this component reads the current token and fires when the token
spells a /k/ sound that closes a syllable, the hard c/k in words like "-ac-", "-ic-",
"-ock", "-ck", "-ch", "rust c". It fires weakly on a c/k that begins a word
(" cat", " close"), on single letters C and K, on q (a /k/ sound), and on a few
function words (" which", " such", " each", " much", " because", " once", " like").
The digit 8 also fires, and so do non-Latin letters with a /k/ sound
(Cyrillic к, Greek κ/χ, Arabic ك, Japanese ka/ki/ku, Chinese 克). It is strongly
negative on the first token of each document or row, where there is no left context.
Everything else is about zero.

The values are rough per-class mean activations fitted on training text. The program
keeps no state beyond the document boundary test, so it reads only the current token
and whether it starts a new document.
"""

READS = ()

WORDS = {" which", " such", " each", " much", " because", " once", " like"}
CODE_FENCE = {"``", "```", " ``", " ```"}
K_SOUND_OTHER = set("кКκΚχΧكکカキクケコ克")
CH_SOUND_OTHER = set("чЧцЦхХ")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        return None, -0.9
    s = tok.strip().lower()
    if tok == "8":
        return None, 0.9
    if tok in WORDS or tok in CODE_FENCE:
        return None, 1.0
    if "�" in tok:
        return None, 0.4
    if s in ("c", "k"):
        return None, 1.0
    if "c" in s or "k" in s:
        if tok.startswith(" ") and s[0] in "ck":
            return None, 0.15
        if s.endswith(("c", "k")):
            return None, 1.0
        return None, 0.5
    if "q" in s:
        return None, 0.4
    if any(ch in K_SOUND_OTHER for ch in tok):
        return None, 0.9
    if any(ch in CH_SOUND_OTHER for ch in tok):
        return None, 0.6
    return None, 0.0

programs.sol:
"""Approximate a mostly quiet, document-opening and source-code cue.

Ordinary text gets a near-zero value. Document beginnings get a negative
baseline depending on spacing, case and script. A few recognizable opening
headers and programming constructs have much larger, signed responses.
A prefix made entirely of one repeated token retains its opening response.
These rules approximate the large excursions, not the small lexical noise.
"""
import regex

READS = ()

# Language declaration starters, when they open a document.
DECLARATIONS = {
    'void': 2.36,
    'int': 0.97,
    'def': 0.10,
    'class': -0.04,
    'import': -0.13,
    'from': -0.98,
    'package': -0.36,
    'const': -0.81,
    '#include': -0.43,
    '<?': -0.76,
}


def opening(s):
    if s in DECLARATIONS:
        return DECLARATIONS[s]
    if s == '<|endoftext|>':
        return 1.40
    if s.startswith('<|'):
        return -0.06
    if s == 'Title':
        return -0.06
    if s == '\r':
        return 0.99
    if s == '^^^^':
        return -2.21
    w = s.strip()
    if not w:
        return -0.12
    if regex.search(r'\p{Script=Han}', w):
        return -0.14
    if regex.search(r'\p{Script=Cyrillic}', w):
        return -0.46
    if w.isascii() and w.isalpha() and w.islower():
        return -0.21 if s[0].isspace() else -0.45
    return -0.25


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        n, first, uniform, previous = 0, s, True, ''
    else:
        _, n, first, uniform, previous = carry
        uniform = uniform and s == first

    value = 0.003
    if uniform:
        value = opening(s)
    elif n == 1:
        if first == 'Title' and s == ':':
            value = 3.15
        elif first == 'package' and s == ' com':
            value = 1.00
        elif first == '#include' and s == ' <':
            value = 0.47
        elif first == '<?' and s == 'php':
            value = 0.78
        elif first.startswith('/*') and s.strip() == '*':
            value = 0.58

    if s.lstrip().startswith('{') and previous.strip() == 'import':
        value = 1.22 if n == 1 else 0.60
    directive = s.strip()
    if directive.startswith('#'):
        directive = directive[1:]
    elif previous.strip() != '#':
        directive = ''
    if n > 0 and directive in {'endif', 'else', 'ifdef', 'ifndef', 'if', 'elif'}:
        value = 0.44 if directive == 'endif' else 0.32

    return (doc, n + 1, first, uniform, s), float(value)

"""Recognize arithmetic continuations of the small constants zero and one.

Negative responses mark lower-bound comparisons, reciprocals, one-plus/minus
expressions (especially inside brackets), 1.0, and phrases like 'one more'.
Ordinary arithmetic on other numbers is much weaker. Only a short text suffix
is retained; it is cleared at document boundaries. Values are approximate
averages, not an attempt to evaluate the arithmetic.
"""
import re

READS = ()


def activation(tail, token):
    s = token.strip()
    word = s.lower()
    if re.search(r'\bone(?: or)?$', tail.lower()):
        if word in ('more', 'less', 'fewer'):
            return -3.7 if tail.lower().endswith(' or') else -5.0
        if word == 'another':
            return -0.5
        if word == 'last':
            return -2.0
    if word == 'than' and re.search(r'\bone (more|less|fewer)$', tail.lower()):
        return -3.5

    # The response falls on the digit after the decimal point, not the dot.
    decimal = re.search(r'([0-9]+)\.\Z', tail)
    if decimal and decimal[1] == '1' and len(s) == 1 and s.isdigit():
        return -1.45 if s == '0' else -0.3

    if s in ('le', 'leq'):
        bound = re.search(r'([01])\s*\\$', tail)
        if bound:
            return -10.0 if bound[1] == '0' else -7.0

    number = re.search(r'([0-9]+(?:\.[0-9]+)?)\Z', tail)
    n = number[1] if number else ''
    before = tail[:number.start()] if number else tail
    if n and before and before[-1].isalnum():
        n = ''  # A numbered identifier is not the constant one.
    bracketed = before.rstrip().endswith(('(', '{', '[', '$'))
    spaced = token[:1].isspace()

    if n == '0' and s in ('-based', '-index', '-indexed'):
        return -8.0
    if s.startswith('</') or (s.startswith('<|') and s.endswith('|>')):
        return 0.0  # Closing tags and special delimiters, not comparisons.
    if s.startswith(('<=', '≤', '≦')):
        if n in ('0', '1'):
            # A lower bound is stronger than a term ending a calculation.
            return -4.0 if before.rstrip().endswith(('=', '+', '-', '−')) else -8.5
        return -1.8 if n else 0.0
    if s.startswith(('<', '＜', '&lt')) and not s.startswith('<<'):
        return -8.0 if n == '0' else (-4.0 if n == '1' else -1.8 if n else 0.0)

    if n == '1':
        if s.startswith('<<'):
            return -8.0 if spaced or bracketed else -3.0
        if s.startswith('}{') and bracketed:
            return -3.3  # LaTeX fraction with numerator one.
        if s.startswith('/'):
            if s.startswith('/('):
                return -3.3
            return -2.9 if bracketed else -2.0
        if s.startswith(('+', '-', '−')):
            attached_word = len(s) > 1 and s[1].isalpha()
            if bracketed:
                return -4.2 if spaced or attached_word else -2.5
            return -1.1 if spaced else -0.5
        if s.startswith('*') and not s.startswith('**'):
            return 0.8
        if s.startswith(('^', '**')):
            return 2.5
    if s in ('+', '-', '−') and (n or tail.endswith(('²', '³'))):
        return -0.4 if tail.endswith(('²', '³')) else -0.15
    if word in ('more', 'less', 'another', 'plus'):
        return 0.15
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = activation(tail, token)
    return (doc, (tail + token)[-80:]), value

"""Approximate a local spelling-continuation signal.

Adjacent letter fragments receive a negative value when joining them gives
an English word, with larger values in magnitude for more familiar words.
Word starts and punctuation are mostly quiet. Broken Unicode tokens have
separate approximate rules. This does not capture lexical exceptions.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=65536)
def continuation(previous, current):
    left = re.search(r'[^\W\d_]+$', previous)
    right = re.match(r'[^\W\d_]+', current)
    adjacent = bool(left and right)
    fragment = left.group() if left else ''
    frequency = (zipf_frequency(fragment + right.group(), 'en')
                 if adjacent else 0.0)
    if frequency <= 0.50:
        if '\ufffd' in previous:
            return -0.635 if '\ufffd' in current else -0.231
        return -0.053 if adjacent else 0.005
    if frequency <= 2.83:
        return -0.206 if len(previous) <= 3 else -0.084
    if frequency <= 3.31:
        return -0.736 if len(previous) <= 1 else -0.275
    if not current.isalpha():
        return 0.027
    if frequency <= 3.58:
        return -0.636 if fragment[0].isupper() else -0.462
    if frequency <= 4.26:
        return -0.866
    return -1.075


def step(carry, prefix, upstream):
    previous = ''
    if (prefix.position and
            prefix.document_ids[-2] == prefix.document_ids[-1]):
        previous = prefix.token_strings[-2]
    return None, continuation(previous, prefix.token_strings[-1])

"""Approximate a signal for punctuation closing short descriptive asides.

Pairs of commas and dashes, and closing parentheses, get negative values
based on the intervening phrase's length and form. Code-like spans are
suppressed; list labels are positive. Ordinary text stays near zero.
A separate, large pulse handles the colon in a document-opening `Title:`
header. First tokens get a small positive baseline.
"""
import math
import re

READS = ()
ASIDE_STARTS = {
    'which', 'who', 'whose', 'whom', 'although', 'though', 'including',
    'especially', 'particularly', 'notably', 'namely', 'formerly', 'both',
    'sometimes', 'together', 'then',
}
ARTICLES = {'a', 'an', 'the'}
DASHES = {' —', ' –', '—', '–', ' --', '--', ' -'}
CONDITIONS = {'if', 'for', 'while', 'switch', 'catch', 'with'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry['doc'] != doc:
        carry = dict(doc=doc, pos=0, comma=None, dash=None, stack=[], line='')
    c = carry
    s = prefix.token_strings[-1]
    pos = c['pos']
    value = 0.0
    if pos == 0:
        value = 0.35
    elif pos == 1 and s == ':' and c['line'] == 'Title':
        value = -29.2
    elif s == ',':
        value = 0.0
        if c['comma'] is not None:
            start, span = c['comma']
            gap = pos-start
            words = re.findall(r"[A-Za-z]+", span.lower())
            if re.search(r'[_=<>;:{}]', span):
                value = 0.0
            elif any(ch.isdigit() for ch in span):
                value = -0.25
            elif len(span) <= 12:
                value = -0.25 if len(words) >= 2 else 0.0
            elif gap > 12:
                value = -0.45 if len(words) < 16 else -0.25
            elif words and (words[0] in ASIDE_STARTS
                            or words[0].endswith(('ed', 'ing'))):
                value = -1.4
            elif words and words[0] in ARTICLES:
                value = -0.95
            else:
                value = -0.75 if len(words) >= 3 else -0.40
    elif s in (')', '）', ']', ' ]'):
        opener = '(' if ')' in s else ('（' if s == '）' else '[')
        value = 0.1
        match = next(
            (x for x in reversed(c['stack']) if x[0] == opener), None
        )
        if re.fullmatch(r'\s*\(?[0-9A-Za-z]+', c['line']):
            value = 0.8
        elif match is not None:
            _, start, spaced, code, span = match
            if code or re.search(r'::|&&|!=|==|\+=|\bself\.', span):
                value = 0.10
            else:
                length = len(span)
                letters = sum(ch.isalpha() for ch in span)
                if not spaced:
                    value = 0.0
                elif length <= 1:
                    value = 0.10
                elif length <= 8:
                    value = -0.45 if letters <= 2 else -0.85
                elif length <= 17:
                    value = -1.15
                else:
                    value = -1.85
                if opener == '[':
                    value *= 0.5
    elif s in DASHES or (s == '-' and c['dash'] is not None):
        value = 0.03
        if c['dash'] is not None:
            start, span = c['dash']
            gap = pos-start
            words = re.findall(r'[A-Za-z]{2,}', span)
            prose = (len(words) >= (2 if '-' in s else 1)
                     and not re.search(r'[0-9_=+*/\\()\[\]{}]', span))
            if prose:
                value -= 4.3*(1-math.exp(-gap/4))*math.exp(-gap/45)
    elif s in ('),', '.,', '.),'):
        value = -0.2
    elif s in ('}', '){'):
        value = 0.2
    elif s in (').', ')\n', ');', '):'):
        value = 0.1
    elif s == '>' and '@' in c['line']:
        value = -1.8

    # Extend only bounded text spans, not the entire prefix.
    if c['dash'] is not None:
        t, text = c['dash']
        c['dash'] = (t, (text+s)[-240:])
    c['stack'] = [(op, t, sp, code, (text+s)[-240:])
                  for op, t, sp, code, text in c['stack']]
    if c['comma'] is not None:
        t, text = c['comma']
        c['comma'] = (t, (text+s)[-240:])
    for ch in s:
        if ch in '([（':
            before = re.findall(r'[A-Za-z]+', c['line'])
            code = bool(before and before[-1] in CONDITIONS)
            c['stack'].append((ch, pos, s.startswith(' ') or ch == '（', code, ''))
        elif ch in ')]）':
            opening = {')':'(', ']':'[', '）':'（'}[ch]
            for i in range(len(c['stack'])-1,-1,-1):
                if c['stack'][i][0] == opening:
                    del c['stack'][i:]
                    break
    if s == ',':
        c['comma'] = (pos, '')
    if s in DASHES:
        c['dash'] = (pos, '')
    if '\n' in s or s in ('.',';',':','<|endoftext|>'):
        c['comma'] = None
        c['dash'] = None
    c['line'] = (c['line']+s).split('\n')[-1][-240:]
    c['pos'] += 1
    return c, value

"""A partial, token-level CJK response profile, amplified in Japanese text.

A kana character within the last 32 tokens marks Japanese context. There,
specific meeting, return, representation and strength roots are positive;
time, attachment and state/shape roots are negative. Corner quotes and
Chinese-form inability/influence expressions have separate negative rules.
These are literal root rules, not a claim that all synonyms behave alike.
Other tokens predict zero. Context resets at document boundaries.
"""
import regex

READS = ()
KANA = regex.compile(r'[\p{Hiragana}\p{Katakana}]')
MEETING = {'会', '大会', '出会'}
TURN_RETURN = {'回', '返'}
REPRESENTATION = {
    '画', '描', '映', '演', '劇', '舞台', '表現', '印象',
}
BEFORE_AFTER = {'前', '後'}
LINK_ATTACH = {'連', '付'}
SHAPE_STATE = {'形', '状', '況'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    t = prefix.position
    last_kana = carry[1] if carry is not None and carry[0] == doc else -1000
    word = prefix.token_strings[-1]
    if KANA.search(word):
        last_kana = t
    japanese = t - last_kana < 32
    carry = (doc, last_kana)

    if any(x in word for x in ('无法', '無法')):  # unable
        return carry, -2.8
    if any(x in word for x in ('没法', '沒法', '没办法', '沒辦法')):
        return carry, -2.2
    if '影响' in word or '影響' in word:  # influence
        return carry, -1.6
    if word.strip() in ('」', '』'):
        outside_japanese = -1.3 if '』' in word else -0.35
        return carry, -3.0 if japanese else outside_japanese
    if word.strip().endswith(('」', '』')):
        return carry, -1.6 if japanese else -0.3
    if word == '『':
        return carry, -1.3 if japanese else -0.7
    if japanese:
        if word in MEETING:
            return carry, 2.5
        if word in TURN_RETURN:
            return carry, 1.8
        if word in REPRESENTATION:
            return carry, 2.2
        if word == '強':  # strong
            return carry, 2.8
        if word == '時':  # time/hour
            return carry, -2.9
        if word == '年':  # year
            return carry, -1.4
        if word in BEFORE_AFTER:
            return carry, -1.8
        if word in LINK_ATTACH:
            return carry, -1.5
        if word in SHAPE_STATE:
            return carry, -1.3
        if (word == '事' and t > 0  # completion of 仕事, work
                and prefix.token_strings[-2].endswith('仕')
                and prefix.document_ids[-2] == doc):
            return carry, 2.0
    return carry, 0.0

"""Lexical pulses, with explicit treatment of document starts and split characters.

Inheritance characters are strongly positive; importance, international terms,
discipline and higher ranks give smaller positive pulses. Release, professional
and protective terminology, cadres, and sensitivity give negative pulses. These are several lexical
families, not a claim that the component represents one unified meaning.

At document starts, source-code opening markers are negative, and 'Title:' has
an especially negative colon. Repeated middle dots are negative anywhere.
For byte-split Han characters, a silk/net radical can already be signalled by
an unfinished character; lustrous-colour characters are negative on completion.
Unlisted cases stay near zero. This deliberately omits many weaker responses.
"""
from functools import lru_cache
import unihan

READS = ()


@lru_cache(maxsize=256)
def mostly_silk_or_net(partial):
    """Do most possible completions have the silk or net radical?"""
    if len(partial) != 2:
        return False
    count = 0
    for last in range(0x80, 0xC0):
        ch = (partial + bytes([last])).decode('utf-8', errors='ignore')
        if len(ch) == 1 and unihan.radical(ch) in (120, 122):
            count += 1
    return count > 32


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', b'')
    _, position, previous, old_partial = carry
    raw = old_partial + prefix.token_bytes[-1]
    text = raw.decode('utf-8', errors='ignore')
    partial = b''
    for n in (1, 2, 3):
        if len(raw) >= n and 0xC2 <= raw[-n] <= 0xF4:
            needed = 2 if raw[-n] < 0xE0 else 3 if raw[-n] < 0xF0 else 4
            if n < needed:
                partial = raw[-n:]
            break
    word = text.strip()
    value = -0.002
    if word in ('继', '繼', '継'):
        value = 7.0 if word == '継' or old_partial else 5.7
    elif word in ('继续', '繼續', '継続'):
        value = 0.65
    elif word == '重要':
        value = 2.6
    elif word in ('的重要', '很重要'):
        value = 2.0
    elif word in ('重要的', '很重要的', '的重要性'):
        value = 0.9
    elif word in ('纪律', '紀律'):
        value = 2.0
    elif word in ('国际', '國際', '际', '際'):
        value = 1.7
    elif word == 'International':
        value = 0.1
    elif word in ('高级', '上级'):
        value = 2.4
    elif word == '級':
        value = 3.0 if previous.endswith(('高', '上')) else 0.4
    elif word in ('中级', '初级', '等级', '各级', '级别', '级别的'):
        value = 0.9
    elif word == '级':
        value = 0.4
    elif word in ('释放', '釋放'):
        value = -1.6
    elif word in ('开放', '開放', '解放'):
