"""Approximate a document-onset pulse using familiar character classes.

The pulse is negative and strongest for words, especially capitalized ones.
Han/kana, digits and punctuation have smaller amplitudes. It continues while
an initial token repeats, then stays near zero until the next document.
A small positive background marks isolated UTF-8 continuation bytes.
Token-specific amplitude differences and rare later pulses are not modeled.
"""
import unicodedata
import regex

READS = ()


def initial_pulse(text):
    if text.startswith('<|'):
        return -150.0
    if not text.strip():
        if '\t' in text:
            return -125.0 if text == '\t' else -90.0
        if '\n' in text or '\r' in text:
            return -53.0
        if text.strip(' ') == '':
            return -28.0 if len(text) == 1 else -78.0
        return -100.0  # Non-ASCII spacing.
    letters = [c for c in text if c.isalpha()]
    if letters:
        if regex.search(r'[\p{Han}\p{Hiragana}\p{Katakana}]', text):
            return -105.0
        value = -133.0 - 18.0 * letters[0].isupper()
        return value + (10.0 if not text.strip().isalpha() else 0.0)
    if text.strip().isdigit():
        return -66.0
    if '\ufffd' in text:
        return -95.0
    symbol = text.strip()
    if len(symbol) > 1:
        return -90.0
    category = unicodedata.category(symbol)
    if category in ('Ps', 'Pi'):  # Opening brackets and quotation marks.
        return -82.0
    if category in ('Pe', 'Pf', 'Pd'):  # Closers and dashes.
        return -50.0
    return -62.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_bytes[-1]
    first = carry is None or carry[0] != doc
    initial_run = first or (carry[2] and token == carry[1])
    value = 0.0
    if initial_run:
        value = initial_pulse(prefix.token_strings[-1])
    elif len(token) == 1 and 0x80 <= token[0] < 0xC0:
        value = 0.4
    return (doc, token, initial_run), value

"""A mixture of lexical and formatting triggers, not one semantic category.

Android View namespaces are strong negatives. First-person guesses,
suppositions, equality methods and TeX accents are positive. The long-s
letter and a Chinese vulgar anatomical character are negative exceptions.
At a document's start, code-comment openers and bare carriage returns
have separate responses. Unrecognized text is predicted as zero.
Only a short byte tail is kept, reset between documents.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = b'' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    before = tail.decode('utf8', 'replace')
    joined = tail + raw
    word = token.strip()
    line = before.rsplit('\n', 1)[-1]
    value = 0.0

    # Document-opening code and decorative formatting.
    if not tail and token in ('//\n', '--', 'def'):
        value = {'//\n': -7.04, '--': -2.14, 'def': 2.03}[token]
    elif raw == b'\r' and not tail.strip(b'\r'):
        value = -4.59
    elif token == '··':
        value = 0.68

    # Java / Android UI names, distinguished from ordinary prose "view".
    elif token == '.view':
        if re.search(r'\bandroid$', before):
            value = -13.2
        elif re.search(r'\bandroid(?:\.[A-Za-z0-9]+)+$', before):
            value = -3.6
    elif token == '.View':
        value = -3.3 if before.endswith('.view') else -1.0
    elif token in ('(View', '<View', '(view'):
        value = -0.55 if token == '(View' else -1.2
    elif word == 'View':
        is_type = token.startswith(' ') and (
            not line.strip() or
            re.search(r'(?:[?:]|\bnew|\bimplements|\bextends)$', before))
        value = -1.6 if is_type else -0.08
        if re.search(r'\b(?:Card|card)$', before):
            value = -1.6
    elif word == 'view' and (
            re.search(r'\b(?:View|var)$', before) or line.isspace()):
        value = -1.8
    elif token in ('.content', '.os', '.net', '.util', '.graphics'):
        if before.endswith(' android'):
            value = {'.content': -3.5, '.os': -2.0, '.net': -2.9,
                     '.util': -1.4, '.graphics': -1.35}[token]
    elif word == 'com' and re.search(r'\bpackage$', before):
        value = 1.7

    # Subject-sensitive English constructions and equality methods.
    elif word in ('guess', 'suppose'):
        if re.search(r'\b[Ii]$', before):
            value = 5.2
        elif word == 'guess':
            value = 1.55 if before.endswith('One') else 0.2
    elif word == 'supposed':
        if re.search(r"\bI was$|['’]m$", before):
            value = 2.6
        elif re.search(r'\b(?:is|was|were|are|am)$', before):
            value = 1.0
        else:
            value = 0.1
    elif token in ('.equals', '.Equals'):
        value = 2.3
    elif word.lower() == 'equals':
        if before.endswith('.'):
            value = 3.3
        elif before.endswith(' boolean'):
            value = 1.1
    elif word == 'equal':
        if before.endswith(' is'):
            value = 0.68
        elif re.search(r'\b(?:are|be|was|were)$', before):
            value = 0.2
        else:
            value = 0.04
    elif word == 'think' and re.search(r'\b[Ii]$', before):
        value = 0.3
    elif word == 'should':
        if re.search(r'\b(?:I|You|We)$', before):
            value = 0.5
        else:
            value = 0.21 if re.search(r'\b(?:you|we)$', before) else 0.02

    # TeX accent commands split across tokens.
    elif token == 'line' and re.search(r'\\(?:over|under)$', before):
        value = 1.4
    elif token == 'dot' and before.endswith('\\'):
        value = 1.7

    # Recognize split characters using bytes rather than replacement glyphs.
    elif raw == b'\xbf' and tail.endswith(b'\xc5'):
        value = -1.8  # historical long s: ſ
    elif raw == b'\x8c' and tail.endswith(b'\xe5\xb1'):
        value = -6.7  # 屌, vulgar Chinese anatomical slang

    return (doc, joined[-192:]), value

