"""Candidate 3: a few word- and code-level concepts.

Negative: the `view` package name in Android Java imports (`import android.view...`),
the strongest single trigger.  Positive: the hedges "I guess" / "I suppose" (first person),
"is supposed to", and the Java/Kotlin `equals` method name.  Everything else predicts 0.
"""
READS = ()

FIRST_PERSON = {"i"}
BE_VERBS = {"is", "was", "am", "are", "were"}
ANDROID_PARTS = {".View", ".content", ".os", ".net"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
