programs.sol:
"""Detect short expressions of singleness, quantity, and degree.

'A single' gives a strong response. Related expressions
('only one', French 'un seul') and the 'of' after collection/amount nouns
also respond. A few degree constructions respond negatively. Unmatched text
gets zero; this deliberately does not memorize arbitrary spelling fragments.
"""
import re

READS = ()
LARGE_COUNTS = {'hundreds', 'thousands', 'millions', 'billions', 'trillions'}
QUANTITY_MODIFIERS = {
    'small', 'large', 'limited', 'considerable', 'certain', 'prime', 'some',
    'substantial'
}
# Familiar collocations: the value is placed on their second word.
PHRASES = {
    ('only', 'one'): 2.4,
    ('just', 'one'): 1.6,
    ('even', 'one'): 1.6,
    ('exactly', 'one'): 1.2,
    ('least', 'one'): 1.2,
    ('almost', 'every'): 1.9,
    ('almost', 'all'): 1.1,
    ('even', 'number'): 1.8,
    ('just', 'how'): -3.0,
    ('just', 'like'): 0.9,
    ('only', 'way'): -1.9,
    ('long', 'way'): -2.5,
    ('good', 'way'): -0.8,
    ('both', 'sides'): -1.7,
    ('right', 'angle'): 2.7,
    ('very', 'truly'): -3.5,
    ('very', 'little'): 1.3,
    ('infinitely', 'many'): 1.5,
    ('une', 'fois'): 2.4,
}


def quantity_of(noun, modifier):
    """Distinguish a stated amount from merely referring to 'the number'."""
    if noun in LARGE_COUNTS:
        return 2.1
    if noun == 'dozens':
        return 1.3
    if noun in {'lot', 'lots', 'majority'}:
        return 1.0
    if noun in {'set', 'list', 'sets', 'lists'}:
        if modifier == 'the':
            return 0.35
        if modifier == 'infinite':
            return 2.4
        return 1.4 if modifier == 'a' or noun.endswith('s') else 1.0
    if noun == 'number':
        if modifier == 'even':
            return 3.6
        return 1.8 if modifier in QUANTITY_MODIFIERS else 0.1
    if noun in {'amount', 'quantity', 'portion', 'fraction', 'percentage'}:
        if modifier in QUANTITY_MODIFIERS:
            return 1.5
        return 1.1 if noun == 'portion' and modifier == 'a' else 0.1
    if noun in {'series', 'sequence', 'sense'}:
        return 0.95 if modifier == 'a' else 0.3
    if noun in {'fraction', 'percentage', 'numbers', 'bunch'}:
        return 0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    words = re.findall(r'[a-z]+', before.lower())
    prev = words[-1] if words else ''
    prev2 = words[-2] if len(words) > 1 else ''
    value = PHRASES.get((prev, word), 0.0)
    if word == 'single':
        value = 4.4 if prev == 'a' else 2.1
        if prev in {'largest', 'third', 'second', 'first', 'lead', 'every'}:
            value = 0.4  # not the emphatic 'a single' construction
    elif word in {'sole', 'seul', 'seule', 'solo'}:
        value = 2.3
        if word == 'solo':
            value = 2.8 if prev in {'un', 'una', 'da'} else 0.7
        elif word in {'seul', 'seule'} and prev in {'un', 'une'}:
            value = 4.8
    elif word == 'solely':
        value = 1.8
    elif word == 'only':
        value = 0.25
        if prev in {'not', 'the', 'can'}:
            value = 0.0
        elif prev in {'with', 'using', 'needs', 'for'}:
            value = 0.8
    elif word == 'of':
        value = quantity_of(prev, prev2)
    elif word == 'from':
        if prev in {'starting', 'start', 'started', 'starts'}:
            value = 6.0 if prev == 'starts' else 4.3
        elif prev in {'just', 'even'}:
            value = 1.7
    elif word == 'once' and prev in {'just', 'only', 'at', 'most'}:
        value = 1.5
    elif word == 'good' and prev in {'very', 'pretty', 'as', 'so'}:
        value = -1.3
    elif word == 'glance' and prev in {'a', 'fleeting'}:
        value = 1.7

    # Recognize the same English stem when tokenization splits it.
    if not token[:1].isspace() and word != 'single':
        old = before.lower()
        if old.endswith(('sin', 'sing', 'singl')):
            if 'single' in (old[-5:] + word):
                value = 7.0
    return (doc, (before + token)[-80:]), float(value)

programs.haiku:
"""Component layers.1.mlp.down_proj:3646, as a program.

The component is a "single / only one" detector. Its activation is near 0 on almost every
token and large and positive on a few words that mean "exactly one, the only one":

- "single" (also "Single", "singled", "sole", "solely", French "seul/seule"): about 2.5,
  and about 4.5 right after "a" or "an" ("a single instance"). It is the biggest effect.
- "one" or "once" right after "only", "just", "exactly" or "even" ("only one"): about 2.2.
- "from" in "starting from" / "starts from" (the origin of a range): about 6.
- "of" after a quantity noun: "a set of", "a list of", "a lot of", "a portion of"
  (about 1.2); "number of", "amount of", "sense of" (about 0.6); "thousands / millions /
  hundreds of" (about 2).

Everything else predicts 0. "alone", "unique" and "individual" do not fire, nor does "one"
in most places. The word matching is done on the text so far, so a word split over tokens
("sing" + "led") is caught on the token that completes it.
"""

READS = ()

ARTICLES = {"a", "an"}
ONLY_BEFORE_ONE = {"only", "just", "exactly", "even"}
START_WORDS = {"start", "starts", "starting", "started"}
QUANTITY_NOUNS = {"set", "sets", "list", "lot", "lots", "portion", "majority", "series",
                  "plenty", "sequence", "fraction"}
WEAK_NOUNS = {"number", "amount", "sense"}
BIG_QUANTITY_NOUNS = {"thousands", "millions", "hundreds"}
SINGLE_WORDS = {"sole", "solely", "seul", "seule"}


def letters(text):
    """The lowercased letters of `text`."""
    return "".join(ch for ch in text.lower() if ch.isalpha())


def trailing_letters(text):
    """The run of letters at the end of `text`, lowercased ('' if none)."""
    word = ""
    for ch in reversed(text):
        if not ch.isalpha():
            break
        word = ch + word
    return word.lower()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.text_prefixes[-2] if same_doc else ""
    if token[:1].isalpha():
        partial = trailing_letters(before)  # letters of this word before this token
        stem = before[: len(before) - len(partial)]
    else:
        partial, stem = "", before          # this token starts a new word
    word = partial + letters(token)         # the word so far, through this token
    prev_word = trailing_letters(stem)      # the word before it

    if "single" in word and "single" not in partial:
        value = 4.5 if prev_word in ARTICLES else 2.5
    elif word in SINGLE_WORDS and word != partial:
        value = 2.5
    elif word in {"one", "once"} and prev_word in ONLY_BEFORE_ONE:
        value = 2.2
    elif word == "from" and prev_word in START_WORDS:
        value = 6.0
    elif word == "of" and prev_word in BIG_QUANTITY_NOUNS:
        value = 2.0
    elif word == "of" and prev_word in QUANTITY_NOUNS:
        value = 1.2
    elif word == "of" and prev_word in WEAK_NOUNS:
        value = 0.6
    else:
        value = 0.0
    return carry, float(value)
